/**
 * useWebcamPiP — webcam de l'orateur incrustée en Picture-in-Picture (V6.E).
 * 100 % natif (getUserMedia + Picture-in-Picture API), zéro-npm, souverain :
 * aucun flux ne quitte la machine. L'orateur pop sa webcam dans une petite
 * fenêtre flottante par-dessus le partage d'écran / le deck projeté.
 *
 * Dégradation propre : `supported=false` si le navigateur n'a pas les API
 * (Firefox n'a pas encore PiP vidéo générale sur tous canaux) → le bouton ne
 * s'affiche pas. Nettoyage des pistes au stop ET au démontage (pas de LED
 * webcam qui reste allumée — incident classique).
 */
import { useCallback, useEffect, useRef, useState } from "react";

interface WebcamPiP {
  supported: boolean;
  active: boolean;
  start: () => Promise<void>;
  stop: () => Promise<void>;
}

function pipSupported(): boolean {
  return (
    typeof navigator !== "undefined" &&
    !!navigator.mediaDevices &&
    typeof navigator.mediaDevices.getUserMedia === "function" &&
    typeof document !== "undefined" &&
    "pictureInPictureEnabled" in document &&
    (document as Document & { pictureInPictureEnabled?: boolean })
      .pictureInPictureEnabled === true
  );
}

export function useWebcamPiP(): WebcamPiP {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [active, setActive] = useState(false);
  const [supported] = useState(pipSupported);

  const stopTracks = useCallback(() => {
    streamRef.current?.getTracks().forEach((t) => t.stop());
    streamRef.current = null;
  }, []);

  const start = useCallback(async () => {
    if (!supported) return;
    const stream = await navigator.mediaDevices.getUserMedia({
      video: true,
      audio: false,
    });
    streamRef.current = stream;
    let v = videoRef.current;
    if (!v) {
      v = document.createElement("video");
      v.muted = true;
      v.playsInline = true;
      videoRef.current = v;
    }
    v.srcObject = stream;
    await v.play();
    await v.requestPictureInPicture();
    setActive(true);
  }, [supported]);

  const stop = useCallback(async () => {
    const doc = document as Document & {
      pictureInPictureElement?: Element | null;
      exitPictureInPicture?: () => Promise<void>;
    };
    if (doc.pictureInPictureElement && doc.exitPictureInPicture) {
      await doc.exitPictureInPicture().catch(() => {});
    }
    stopTracks();
    setActive(false);
  }, [stopTracks]);

  // Démontage : coupe la webcam même si l'orateur ferme sans « stop ».
  useEffect(() => () => stopTracks(), [stopTracks]);

  return { supported, active, start, stop };
}
