/**
 * useFocusTrap — le piège de focus des VOILES : une boîte plein écran qui
 * bloque le reste de la page garde le clavier en elle.
 *
 * POURQUOI ICI (2026-10-05, chapitre « L'overlay », étape des voiles)
 *
 * L'inventaire des voiles plein écran en a compté 27 en production hors
 * `SafeModal`, `SafeDrawer` et Ant ; sur les 21 boîtes, 5 seulement gardaient
 * le focus, et trois pièges coexistaient — celui-ci (né dans la visio, un seul
 * appelant), celui de la visite guidée, celui de la commande vocale. Il
 * devient le moteur commun plutôt que d'en écrire un quatrième ; l'ancien
 * chemin (`shared/hooks/meeting/useAccessibility`) le réexporte.
 *
 * Ce qu'il garantit :
 * 1. à l'ouverture, le focus entre DANS la boîte : `initialFocus` (sélecteur),
 *    sinon le premier élément focalisable, sinon la boîte elle-même ;
 * 2. Tab et Maj+Tab bouclent à l'intérieur — et un focus parti dehors (un clic
 *    sur le voile, un élément démonté) est ramené dedans, sauf s'il est passé
 *    à une surcouche ouverte AU-DESSUS (confirmation, tiroir, menu : leur
 *    portail vit hors de la boîte) ;
 * 3. Échap appelle `onEscape` — SEULEMENT quand le focus est dans la boîte :
 *    une confirmation ouverte par-dessus tient le focus, et c'est elle qui
 *    reçoit Échap la première ;
 * 4. à la fermeture, le focus revient à l'élément qui l'avait.
 *
 * Les focalisables se lisent sans géométrie (`offsetParent` est toujours
 * `null` dans jsdom, et l'ancien filtre rendait la boîte vide en banc) : sont
 * écartés les éléments désactivés, `tabindex="-1"`, et ce qui est sous
 * `[hidden]`, `[inert]` ou `aria-hidden="true"`.
 */
import { useCallback, useEffect, useRef } from "react";

export interface UseFocusTrapOptions {
  enabled?: boolean;
  /** Sélecteur CSS de l'élément qui reçoit le focus à l'ouverture. */
  initialFocus?: string;
  /** Rendre le focus à l'élément qui l'avait, à la fermeture (défaut : oui). */
  returnFocus?: boolean;
  /** Échap appelle `onEscape` (défaut : oui). */
  escapeDeactivates?: boolean;
  onEscape?: () => void;
}

/* `iframe` compris : l'éditeur Collabora agrandi est un voile dont le document
   vit dans une iframe — l'oublier ferait sauter le document à la boucle de Tab,
   et le clavier ne pourrait plus y entrer. */
const FOCALISABLES = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "iframe",
  "audio[controls]",
  "video[controls]",
  '[contenteditable="true"]',
  '[tabindex]:not([tabindex="-1"])',
].join(", ");

function estAtteignable(el: HTMLElement): boolean {
  if (el.getAttribute("tabindex") === "-1") return false;
  return !el.closest('[hidden], [inert], [aria-hidden="true"]');
}

/**
 * Les éléments focalisables d'un conteneur, dans l'ordre du document, lus sans
 * géométrie (voir l'en-tête). Exporté le 2026-10-08 pour le cycle de Tab de
 * l'auvent, qui borne son parcours au cadre et au panneau sans être un voile :
 * un seul lecteur de focalisables plutôt qu'une seconde liste de sélecteurs.
 */
export function focalisablesDe(conteneur: ParentNode): HTMLElement[] {
  return Array.from(conteneur.querySelectorAll<HTMLElement>(FOCALISABLES)).filter(
    estAtteignable,
  );
}

/* UNE SURCOUCHE OUVERTE DEPUIS LA BOÎTE VIT DANS UN PORTAIL (2026-10-06). Une
   confirmation, un tiroir, un menu ouverts depuis un voile naissent hors de son
   DOM : le focus qui y est n'est pas « parti », il est passé à la couche du
   dessus. Rapatrié au Tab, il rendait la confirmation inutilisable au clavier —
   « Terminer l'appel ? » depuis la reconnexion de la salle, une confirmation
   depuis l'éditeur agrandi. Une couche qui CONTIENT la boîte est en dessous
   d'elle (un voile monté dans un tiroir) : le focus y revient. */
const COUCHES = [
  '[aria-modal="true"]',
  ".ant-modal-root",
  ".ant-drawer",
  ".ant-popover",
  ".ant-dropdown",
  ".ant-select-dropdown",
  ".ant-picker-dropdown",
].join(", ");

/** Exporté le 2026-10-08 : l'auvent laisse lui aussi son Tab à une surcouche ouverte par-dessus. */
export function dansUneCoucheAuDessus(boite: HTMLElement, el: Element | null): boolean {
  const couche = el?.closest(COUCHES);
  return !!couche && couche !== boite && !couche.contains(boite);
}

export function useFocusTrap<T extends HTMLElement = HTMLElement>(
  options: UseFocusTrapOptions = {},
) {
  const {
    enabled = true,
    initialFocus,
    returnFocus = true,
    escapeDeactivates = true,
    onEscape,
  } = options;

  const containerRef = useRef<T>(null);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  /* La dernière version de `onEscape`, lue au moment de la touche : l'écouteur
     ne se réabonne pas à chaque rendu de l'appelant. */
  const onEscapeRef = useRef(onEscape);
  onEscapeRef.current = onEscape;

  const focalisables = useCallback((): HTMLElement[] => {
    const boite = containerRef.current;
    return boite ? focalisablesDe(boite) : [];
  }, []);

  // 1 et 4 — le focus entre à l'ouverture, revient à la fermeture.
  useEffect(() => {
    const boite = containerRef.current;
    if (!enabled || !boite) return;

    previousFocusRef.current = document.activeElement as HTMLElement | null;

    const cible =
      (initialFocus ? boite.querySelector<HTMLElement>(initialFocus) : null) ??
      focalisables()[0] ??
      boite;
    if (cible === boite && !boite.hasAttribute("tabindex")) {
      boite.setAttribute("tabindex", "-1");
    }
    /* Une frame : la boîte vient d'être montée, son contenu peut l'être un
       instant plus tard (portail, animation d'entrée). */
    const frame = requestAnimationFrame(() => {
      if (!boite.contains(document.activeElement)) cible.focus();
    });

    return () => {
      cancelAnimationFrame(frame);
      if (returnFocus) previousFocusRef.current?.focus?.();
    };
  }, [enabled, initialFocus, returnFocus, focalisables]);

  // 2 et 3 — Tab boucle, Échap ferme.
  useEffect(() => {
    if (!enabled) return;

    const surTouche = (event: KeyboardEvent) => {
      const boite = containerRef.current;
      if (!boite) return;
      const dedans = boite.contains(document.activeElement);

      if (event.key === "Escape") {
        if (!escapeDeactivates || !dedans || !onEscapeRef.current) return;
        event.preventDefault();
        event.stopPropagation();
        onEscapeRef.current();
        return;
      }

      if (event.key !== "Tab") return;
      if (!dedans && dansUneCoucheAuDessus(boite, document.activeElement)) return;
      const liste = focalisables();
      if (liste.length === 0) {
        event.preventDefault();
        boite.focus();
        return;
      }
      const premier = liste[0];
      const dernier = liste[liste.length - 1];
      const actif = document.activeElement;

      if (!dedans) {
        event.preventDefault();
        (event.shiftKey ? dernier : premier).focus();
      } else if (event.shiftKey && actif === premier) {
        event.preventDefault();
        dernier.focus();
      } else if (!event.shiftKey && actif === dernier) {
        event.preventDefault();
        premier.focus();
      }
    };

    document.addEventListener("keydown", surTouche);
    return () => document.removeEventListener("keydown", surTouche);
  }, [enabled, escapeDeactivates, focalisables]);

  return { containerRef };
}
