/**
 * Handler clavier du moteur (extrait du shell — ratchet règle 23, audit
 * 2026-07-05) + touches de fiabilité jour J découvertes à la passe
 * d'amélioration :
 *  - `F5` : le bouton « diaporama » du clicker Logitech R400/R700/R800 émet
 *    F5 → sans capture, le navigateur RECHARGE la page en pleine séance
 *    (retour scène 1). On le capture : preventDefault + démarrer le plein
 *    écran, jamais de reload.
 *  - `Enter` / pavé numérique Enter : télécommandes génériques et Spotlight en
 *    mode « Enter » → avancer.
 *  - `B`/`W`/`.` : coupure d'écran (le 3ᵉ bouton « blank » du R400 émet `.`,
 *    convention PowerPoint ; B = noir, W = blanc, standard Keynote). Toute
 *    touche de navigation lève la coupure ET navigue (comportement Keynote).
 *
 * Le listener est attaché UNE fois ; les actions sont lues via ref pour
 * refléter les dernières closures sans re-binder (évite les fuites de
 * re-attach à chaque render).
 */
import { useEffect, useRef } from "react";

import type {
  BlackoutMode,
  PresentationScene,
} from "./presentation-definition";

export interface PresentationKeyActions {
  standby: boolean;
  dismissStandby: () => void;
  forward: () => void;
  backward: () => void;
  stepBack: () => void;
  goToScene: (next: number, revealAll?: boolean) => void;
  mainCount: number;
  scenes: PresentationScene[];
  sceneIsAppendix: boolean;
  toggleFullscreen: () => void;
  startFullscreen: () => void;
  isPresenter: boolean;
  overviewOpen: boolean;
  setOverview: (v: boolean | ((prev: boolean) => boolean)) => void;
  blackout: BlackoutMode | null;
  setBlackout: (v: BlackoutMode | null) => void;
  /** Mode solo : une navigation manuelle met l'auto-avance en pause (optionnel). */
  onManualNav?: () => void;
}

const NAV_KEYS = new Set([
  "ArrowRight",
  "PageDown",
  " ",
  "ArrowDown",
  "ArrowLeft",
  "PageUp",
  "ArrowUp",
  "Home",
  "End",
  "Enter",
]);

function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName;
  if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return true;
  if (target.isContentEditable) return true;
  return Boolean(
    target.closest(".ant-drawer, .ant-modal, .ant-select-dropdown"),
  );
}

export function usePresentationKeys(actions: PresentationKeyActions): void {
  const ref = useRef(actions);
  ref.current = actions;

  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      const a = ref.current;
      if (isTypingTarget(e.target)) return;

      // Le premier keypress lève l'écran d'accueil, sans naviguer.
      if (a.standby) {
        e.preventDefault();
        a.dismissStandby();
        return;
      }

      // Coupure active : toute touche la lève ; une touche de navigation
      // navigue en plus (standard Keynote), les autres s'arrêtent là.
      if (a.blackout) {
        a.setBlackout(null);
        if (!NAV_KEYS.has(e.key)) {
          e.preventDefault();
          return;
        }
      }

      // Mode solo : toute touche qui déplace la position (nav, chiffre, A)
      // rend la main au destinataire → l'auto-avance se met en pause.
      if (NAV_KEYS.has(e.key) || /^[1-9aA]$/.test(e.key)) a.onManualNav?.();

      switch (e.key) {
        case "ArrowRight":
        case "PageDown":
        case " ":
        case "ArrowDown":
        case "Enter":
          e.preventDefault();
          a.forward();
          break;
        case "ArrowLeft":
        case "PageUp":
          e.preventDefault();
          a.backward();
          break;
        case "ArrowUp":
          e.preventDefault();
          a.stepBack();
          break;
        case "Home":
          e.preventDefault();
          a.goToScene(0);
          break;
        case "End":
          e.preventDefault();
          a.goToScene(a.mainCount - 1, true);
          break;
        case "F5":
          // JAMAIS de reload en séance — sémantique « démarrer » du clicker.
          e.preventDefault();
          a.startFullscreen();
          break;
        case "b":
        case "B":
        case ".":
          e.preventDefault();
          a.setBlackout(a.blackout === "black" ? null : "black");
          break;
        case "w":
        case "W":
          e.preventDefault();
          a.setBlackout(a.blackout === "white" ? null : "white");
          break;
        case "a":
        case "A": {
          e.preventDefault();
          const firstAppendix = a.scenes.findIndex((s) => s.appendix);
          if (firstAppendix >= 0)
            a.goToScene(a.sceneIsAppendix ? 0 : firstAppendix, true);
          break;
        }
        case "Escape":
          if (a.isPresenter) break;
          if (a.overviewOpen) {
            e.preventDefault();
            a.setOverview(false);
            break;
          }
          // En plein écran, le navigateur sort du fullscreen sur Escape :
          // ne PAS ouvrir aussi le sommaire par-dessus (sortie + overlay
          // simultanés = confus ; le pill de garde couvre le retour).
          if (document.fullscreenElement) break;
          e.preventDefault();
          a.setOverview(true);
          break;
        case "o":
        case "O":
          if (a.isPresenter) break;
          e.preventDefault();
          a.setOverview((v) => !v);
          break;
        case "f":
        case "F":
          e.preventDefault();
          a.toggleFullscreen();
          break;
        default: {
          const n = Number.parseInt(e.key, 10);
          if (!Number.isNaN(n) && n >= 1 && n <= Math.min(9, a.mainCount)) {
            e.preventDefault();
            a.goToScene(n - 1, true);
          }
        }
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);
}
