/**
 * PresentationShell v5 — moteur de présentation plein écran.
 *
 * v3 : clavier / transitions / progression / dots / fullscreen / dark.
 * v4 : zéro défilement de page (scroll en cadre interne), dock dev masqué.
 * v5 (gaps audit externe 2026-07-03) :
 *   - FRAGMENTS pilotés : → / Espace / PgDn révèlent le fragment suivant PUIS
 *     passent à la scène suivante (standard Reveal) ; ↑ recule d'un fragment ;
 *     ← / PgUp = scène précédente (fragments de la cible tous révélés).
 *   - MODE PRÉSENTATEUR : `?presenter` ouvre la vue notes + suivante + chrono ;
 *     synchronisation bidirectionnelle BroadcastChannel (audience ↔ pupitre).
 *   - APPENDIX : scènes `appendix: true` HORS flux principal (→ s'arrête à la
 *     dernière scène normale) — accès touche A, dots dans un groupe séparé.
 *   - SOMMAIRE : Échap / O = overlay listant les scènes (navigation directe).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { useFocusTrap } from "@/shared/hooks/useFocusTrap";
import { flushSync } from "react-dom";

import { FragmentStepContext } from "./fragments";
import { SceneNumberContext } from "./scene-number";
import { PresenterView } from "./PresenterView";
import {
  BlackoutLayer,
  CornerBtn,
  CornerNav,
  Dot,
  DotsGroupGap,
  DotsNav,
  FullscreenLostPill,
  HideDevChrome,
  KeysHint,
  PresentationVT,
  OverviewItem,
  OverviewLayer,
  OverviewList,
  OverviewTitle,
  ProgressFill,
  ProgressTrack,
  SceneCounter,
  SceneViewport,
  Stage,
} from "./presentation.styles";
import { useSentryFeatureTag } from "@/shared/hooks/useSentryFeatureTag";

import { A11yScaffold } from "./A11yScaffold";
import { SoloOverlay } from "./SoloOverlay";
import { useFullscreenGuard } from "./use-fullscreen-guard";
import { usePresentationKeys } from "./use-presentation-keys";
import {
  autoGuideRequested,
  usePresentationRuntime,
} from "./use-presentation-runtime";
import { usePresentationSync } from "./use-presentation-sync";
import {
  readPersistedPosition,
  usePersistPosition,
} from "./use-persisted-position";
import { useProjector } from "./use-projector";
import { useWakeLock } from "./use-wake-lock";

import type {
  BlackoutMode,
  PresentationDefinition,
  PresentationScene,
  PresentationSyncState,
} from "./presentation-definition";

// Re-export pour compat des consommateurs historiques (parcours.tsx importe
// PresentationScene depuis le shell).
export type {
  PresentationScene,
  PresentationSyncState,
  PresentationDefinition,
};

type PresentationShellProps = PresentationDefinition;

/** Channel de sync par défaut (générique — un deck peut l'isoler via `channelId`). */
export const DEFAULT_PRESENTATION_CHANNEL = "presentation-engine-sync";

export function PresentationShell({
  scenes,
  notes,
  title,
  renderStandby,
  channelId = DEFAULT_PRESENTATION_CHANNEL,
  parts,
}: PresentationShellProps) {
  const isPresenter = useMemo(
    () => new URLSearchParams(window.location.search).has("presenter"),
    [],
  );
  const total = scenes.length;
  const mainCount = useMemo(
    () => scenes.filter((s) => !s.appendix).length,
    [scenes],
  );
  // Reprise après crash/reload SOLO (sans pupitre) : position restaurée depuis
  // sessionStorage avant tout render (fiabilité jour J, audit 2026-07-05).
  // Clamp aux bornes du deck COURANT : la position sauvegardée peut pointer
  // sur une scène qui n'existe plus (deck raccourci à chaud — incident
  // 2026-07-10, 47 → 39 scènes = crash `scenes[index].fragments` au render).
  const persisted = useMemo(() => {
    const raw = readPersistedPosition(channelId);
    const safeIndex = Math.max(0, Math.min(raw.index, scenes.length - 1));
    const safeStep = Math.min(raw.step, scenes[safeIndex]?.fragments ?? 0);
    return { ...raw, index: safeIndex, step: safeStep };
  }, [channelId, scenes]);
  const [index, setIndex] = useState(persisted.index);
  const [step, setStep] = useState(persisted.step);
  const [dir, setDir] = useState<1 | -1>(1);
  // Écran d'accueil projeté à l'arrivée (dismissé au 1er keypress/clic) —
  // désactivé en présentateur, si `?nostandby`, ou si une séance démarrée est
  // restaurée (on reprend en pleine présentation, pas à l'accueil).
  const [standby, setStandby] = useState(
    () =>
      Boolean(renderStandby) &&
      !new URLSearchParams(window.location.search).has("nostandby") &&
      // Auto-guidé (solo/kiosk) : pas d'accueil bloquant, lecture d'emblée.
      !autoGuideRequested() &&
      !persisted.restored,
  );
  const [hintFaded, setHintFaded] = useState(false);
  const [overview, setOverview] = useState(false);
  /* Le sommaire est une boîte modale (chapitre « L'overlay », 2026-10-05) :
     le focus y entre — sur la scène en cours —, y boucle, et revient à la
     scène quand il se referme. Échap reste celui des touches de la
     présentation, qui le referment déjà. */
  const { containerRef: sommaireRef } = useFocusTrap<HTMLDivElement>({
    enabled: overview,
    escapeDeactivates: false,
    initialFocus: '[aria-current="true"]',
  });
  const [startedAt, setStartedAt] = useState<number | null>(
    persisted.startedAt,
  );
  const [blackout, setBlackout] = useState<BlackoutMode | null>(null);
  const stageRef = useRef<HTMLDivElement>(null);

  // Morphing View Transitions (gap 16) : natif quand supporté, sinon le
  // slide-in keyframes actuel — dégradation gracieuse sans branche de code.
  const vtSupported = useMemo(
    () =>
      typeof (document as Document & { startViewTransition?: unknown })
        .startViewTransition === "function" &&
      !window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    [],
  );

  const scene = scenes[index];
  const sceneFragments = scene.fragments ?? 0;
  const hasAppendix = useMemo(() => scenes.some((s) => s.appendix), [scenes]);

  // Titre d'onglet piloté par le deck (audience ET pupitre identifiables dans
  // la barre d'onglets quand plusieurs sont ouverts) — restauré au démontage.
  useEffect(() => {
    if (!title) return;
    const previous = document.title;
    document.title = isPresenter ? `${title} — pupitre` : title;
    return () => {
      document.title = previous;
    };
  }, [title, isPresenter]);

  /* ── Synchronisation audience ↔ présentateur (protocole hello) ────────── */

  usePresentationSync(
    channelId,
    { index, step, startedAt, blackout },
    (remote) => {
      // Même clamp que la restauration : un pair resté sur une version plus
      // longue du deck peut annoncer un index au-delà de nos scènes.
      const i = Math.max(0, Math.min(remote.index, total - 1));
      const { step: s, startedAt: t } = remote;
      setIndex((cur) => {
        if (i !== cur) setDir(i > cur ? 1 : -1);
        return i;
      });
      setStep(s);
      setStartedAt(t);
      setBlackout(remote.blackout ?? null); // coupure pilotée depuis le pupitre
      // Écran projeté piloté depuis le pupitre : dès que l'état distant
      // indique une présentation démarrée, l'accueil tombe tout seul (sinon
      // il faudrait venir cliquer la fenêtre projetée). L'état de repos
      // {0, 0, null} ne dismisse pas.
      if (i > 0 || s > 0 || t !== null) setStandby(false);
    },
  );

  // Persistance de position (reprise après crash/reload — voir hook).
  usePersistPosition(channelId, { index, step, startedAt });

  /* ── Navigation (fragments d'abord, standard Reveal) ──────────────────── */

  const goToScene = useCallback(
    (next: number, revealAll = false) => {
      const clamped = Math.max(0, Math.min(total - 1, next));
      const apply = () => {
        setIndex((current) => {
          if (clamped === current) {
            // Même scène : révéler quand même ses fragments si demandé
            // (clic sur le dot de la scène courante — constat revue visuelle).
            if (revealAll) setStep(scenes[clamped].fragments ?? 0);
            return current;
          }
          setDir(clamped > current ? 1 : -1);
          setStep(revealAll ? (scenes[clamped].fragments ?? 0) : 0);
          return clamped;
        });
        setStartedAt((t) => t ?? Date.now());
      };
      const doc = document as Document & {
        startViewTransition?: (cb: () => void) => unknown;
      };
      if (vtSupported && typeof doc.startViewTransition === "function") {
        doc.startViewTransition(() => {
          flushSync(apply);
        });
      } else {
        apply();
      }
    },
    [total, scenes, vtSupported],
  );

  const forward = useCallback(() => {
    if (step < sceneFragments) {
      setStep(step + 1);
      setStartedAt((t) => t ?? Date.now());
      return;
    }
    // Le flux principal s'arrête avant l'appendix (accès dédié touche A) —
    // mais UNE FOIS dans l'appendix, → navigue librement d'annexe en annexe
    // (bug jour-J : coincé sur A1 sinon, découvert probe v12).
    const nextIsAppendix = index + 1 < total && scenes[index + 1].appendix;
    if (index + 1 < total && (!nextIsAppendix || scenes[index].appendix)) {
      goToScene(index + 1);
    }
  }, [step, sceneFragments, index, total, scenes, goToScene]);

  const backward = useCallback(() => {
    // Symétrique de forward : ← replie d'abord les fragments (la roue anim /
    // les listes reviennent en arrière), et ne recule de scène qu'une fois au
    // premier fragment (feedback user : ← quittait la scène au lieu de dérouler
    // l'animation à rebours).
    if (step > 0) {
      setStep(step - 1);
      return;
    }
    goToScene(index - 1, true);
  }, [step, index, goToScene]);

  const stepBack = useCallback(() => {
    if (step > 0) setStep(step - 1);
  }, [step]);

  // Conversion traçable (V6.A) : analytics par scène (tous modes) + mode solo
  // (auto-avance + pause). Tout le concern vit dans le hook dédié.
  const {
    isAutoGuided,
    playbackMode,
    autoPaused,
    pauseAuto,
    resumeAuto,
    atMainEnd,
    dwellMs,
    stepKey,
  } = usePresentationRuntime({
    scenes,
    scene,
    index,
    step,
    sceneFragments,
    total,
    mainCount,
    isPresenter,
    channelId,
    standby,
    blackout,
    forward,
    restart: () => goToScene(0),
  });

  // Observabilité (V1.d) : tag scopé au montage du shell, retiré au unmount
  // (jamais de setTag global qui colorerait les erreurs des autres pages).
  useSentryFeatureTag("presentation-engine");

  // Fiabilité jour J + multi-écran (GO user 2026-07-05) — hooks dédiés.
  useWakeLock(!isPresenter);
  const { fullscreenLost, markVoluntaryExit, dismissFullscreenLost } =
    useFullscreenGuard();
  const { projectorAvailable, sendToProjector } = useProjector(stageRef);

  const toggleFullscreen = useCallback(() => {
    if (document.fullscreenElement) {
      markVoluntaryExit(); // sortie demandée (bouton/F) : pas d'alerte
      void document.exitFullscreen();
    } else {
      void stageRef.current?.requestFullscreen();
    }
  }, [markVoluntaryExit]);

  // « Démarrer le diaporama » (touche F5 du clicker) : entrer en plein écran,
  // jamais en sortir (F5 ≠ toggle) — évite le reload ET une sortie accidentelle.
  const startFullscreen = useCallback(() => {
    if (!document.fullscreenElement) void stageRef.current?.requestFullscreen();
  }, []);

  usePresentationKeys({
    standby,
    dismissStandby: () => setStandby(false),
    forward,
    backward,
    stepBack,
    goToScene,
    mainCount,
    scenes,
    sceneIsAppendix: Boolean(scene.appendix),
    toggleFullscreen,
    startFullscreen,
    isPresenter,
    overviewOpen: overview,
    setOverview,
    blackout,
    setBlackout,
    onManualNav: pauseAuto,
  });

  /* ── Aide clavier auto-estompée ───────────────────────────────────────── */

  useEffect(() => {
    const timer = window.setTimeout(() => setHintFaded(true), 7000);
    const onMove = () => setHintFaded(false);
    window.addEventListener("mousemove", onMove);
    return () => {
      window.clearTimeout(timer);
      window.removeEventListener("mousemove", onMove);
    };
  }, []);

  useEffect(() => {
    if (hintFaded) return;
    const timer = window.setTimeout(() => setHintFaded(true), 7000);
    return () => window.clearTimeout(timer);
  }, [hintFaded]);

  const pad = (n: number) => String(n).padStart(2, "0");

  if (isPresenter) {
    return (
      <PresenterView
        scenes={scenes}
        notes={notes ?? {}}
        index={index}
        step={step}
        startedAt={startedAt}
        parts={parts}
        blackout={blackout}
        onForward={forward}
        onBackward={backward}
        onGoTo={goToScene}
        onResetTimer={() => setStartedAt(Date.now())}
      />
    );
  }

  return (
    <Stage ref={stageRef}>
      <HideDevChrome />
      <PresentationVT />
      <A11yScaffold
        contentId="pb-scene-content"
        sceneLabel={scene.label}
        sceneIndex={index}
        mainCount={mainCount}
        appendix={scene.appendix}
      />
      {standby && renderStandby ? renderStandby(() => setStandby(false)) : null}
      <ProgressTrack aria-hidden>
        <ProgressFill
          style={{
            width: `${((Math.min(index, mainCount - 1) + 1) / mainCount) * 100}%`,
          }}
        />
      </ProgressTrack>

      <FragmentStepContext.Provider value={step}>
        <SceneNumberContext.Provider
          value={scene.appendix ? `A${index - mainCount + 1}` : pad(index + 1)}
        >
          <SceneViewport
            id="pb-scene-content"
            key={scene.id}
            $dir={dir}
            $animate={!vtSupported}
          >
            {scene.render()}
          </SceneViewport>
        </SceneNumberContext.Provider>
      </FragmentStepContext.Provider>

      {fullscreenLost ? (
        <FullscreenLostPill
          type="button"
          onClick={() => (
            dismissFullscreenLost(),
            void stageRef.current?.requestFullscreen()
          )}
          aria-label="Le plein écran a été quitté — cliquer pour y revenir"
        >
          Plein écran quitté — revenir (F)
        </FullscreenLostPill>
      ) : null}

      <CornerNav>
        <CornerBtn
          type="button"
          $dark={scene.dark}
          onClick={() =>
            window.open(
              `${window.location.pathname}?presenter`,
              // Nom de fenêtre dérivé du deck (était hardcodé au barreau) :
              // deux présentations n'écrasent plus la fenêtre pupitre l'une de
              // l'autre, et rouvrir réutilise la même fenêtre.
              `presenter-${channelId}`,
              "width=1100,height=700",
            )
          }
          aria-label="Ouvrir la vue présentateur (notes, scène suivante, chrono)"
        >
          Présentateur
        </CornerBtn>
        {projectorAvailable && !isPresenter ? (
          <CornerBtn
            type="button"
            $dark={scene.dark}
            onClick={() => void sendToProjector()}
            aria-label="Envoyer la présentation en plein écran sur le projecteur (écran externe)"
            title="Plein écran ciblé sur l'écran externe (Window Management, Chromium)"
          >
            → Projecteur
          </CornerBtn>
        ) : null}
        <CornerBtn
          type="button"
          $dark={scene.dark}
          onClick={toggleFullscreen}
          aria-label="Plein écran · F — basculer le plein écran"
          title={title ? `${title} — plein écran (F)` : "Plein écran (F)"}
        >
          Plein écran · F
        </CornerBtn>
      </CornerNav>

      <SceneCounter $dark={scene.dark}>
        {pad(index + 1)} / {pad(total)}
        {sceneFragments > 0 ? ` · ${step}/${sceneFragments}` : ""}
      </SceneCounter>

      <DotsNav
        $dark={scene.dark}
        aria-label={`Navigation entre les volets de la présentation (${total} au total)`}
      >
        {scenes.map((s, i) => (
          <span key={s.id} style={{ display: "inline-flex" }}>
            {s.appendix && !scenes[i - 1]?.appendix ? (
              <DotsGroupGap aria-hidden />
            ) : null}
            <Dot
              type="button"
              $active={i === index}
              $dark={scene.dark}
              aria-label={`Volet ${i + 1} — ${s.label}${s.appendix ? " (appendix)" : ""}`}
              aria-current={i === index ? "step" : undefined}
              title={s.label}
              onClick={() => {
                pauseAuto();
                goToScene(i, true);
              }}
            />
          </span>
        ))}
      </DotsNav>

      <KeysHint $dark={scene.dark} $faded={hintFaded} aria-hidden>
        → dérouler · ← retour · O sommaire{hasAppendix ? " · A annexes" : ""} ·
        F plein écran
      </KeysHint>

      {/* Auto-guidé (solo/kiosk) : badge + barre de dwell / pastille de reprise. */}
      <SoloOverlay
        active={isAutoGuided}
        mode={playbackMode}
        atMainEnd={atMainEnd}
        autoPaused={autoPaused}
        dark={scene.dark}
        dwellMs={dwellMs}
        stepKey={stepKey}
        onResume={resumeAuto}
      />

      {overview ? (
        <OverviewLayer
          ref={sommaireRef}
          role="dialog"
          aria-modal="true"
          aria-label="Sommaire de la présentation"
        >
          <OverviewTitle>Sommaire</OverviewTitle>
          <OverviewList>
            {scenes.map((s, i) => (
              <OverviewItem
                key={s.id}
                type="button"
                aria-current={i === index ? "true" : undefined}
                $active={i === index}
                $appendix={s.appendix}
                onClick={() => {
                  pauseAuto();
                  goToScene(i, true);
                  setOverview(false);
                }}
              >
                <span>{pad(i + 1)}</span> {s.label}
                {s.appendix ? " · annexe" : ""}
              </OverviewItem>
            ))}
          </OverviewList>
        </OverviewLayer>
      ) : null}

      {blackout ? (
        <BlackoutLayer
          $mode={blackout}
          role="button"
          tabIndex={0}
          aria-label={`Écran ${blackout === "white" ? "blanc" : "noir"} — toucher ou appuyer sur une touche pour reprendre`}
          onClick={() => setBlackout(null)}
        />
      ) : null}
    </Stage>
  );
}
