/**
 * Mode répétition chronométré (moteur V3.c, 2026-07-05) — remplace le tableau
 * « cible / réel » rempli à la main du runbook.
 *
 * En mode présentateur, capture le timestamp de PREMIÈRE entrée dans chaque
 * partie (jalon `startIndex`) et calcule, pour la partie courante et les
 * passées, le réel cumulé vs la cible cumulée + l'écart. Le présentateur voit
 * s'il est en avance ou en retard, partie par partie, sans chronomètre externe.
 *
 * Pur calcul dérivé d'un Map de franchissements (useRef) — aucun réseau.
 * Les franchissements sont PERSISTÉS par séance (localStorage, clé dérivée de
 * `startedAt` — unique par séance et restauré par le protocole hello) : un
 * pupitre fermé/rouvert en cours de répétition retrouve les réels des parties
 * déjà passées (P2 d'audit 2026-07-05 — avant, seul le chrono global
 * survivait au remount).
 */
import { useRef } from "react";

import {
  getStorageItem,
  getStorageKeys,
  removeStorageItem,
  setStorageItem,
} from "@/shared/utils/storage";

import type { PresentationPart } from "./presentation-definition";

const STORAGE_PREFIX = "presentation-rehearsal:";

// Moteur Storage canonique (règle 85) : JSON-safe, garde mode privé/quota —
// storage indisponible → fallback [] = mode mémoire seule, sans throw.
function readSeance(key: string): Map<number, number> {
  const entries = getStorageItem<[number, number][]>(key, []);
  return new Map(entries.map(([k, v]) => [Number(k), Number(v)]));
}

function writeSeance(key: string, reached: Map<number, number>) {
  // Une seule séance vivante : purger les clés des séances précédentes.
  for (const k of getStorageKeys(STORAGE_PREFIX))
    if (k !== key) removeStorageItem(k);
  setStorageItem(key, [...reached.entries()]);
}

export interface RehearsalRow {
  label: string;
  targetMinCumulative: number;
  /** Minutes réelles cumulées à l'entrée de la partie (null si pas atteinte). */
  realMinCumulative: number | null;
  /** réel − cible (négatif = en avance, positif = en retard). null si non atteinte. */
  deltaMin: number | null;
  /** Partie actuellement en cours. */
  current: boolean;
}

export function useRehearsalTimer(
  parts: PresentationPart[] | undefined,
  index: number,
  startedAt: number | null,
  now: number,
): RehearsalRow[] {
  // startIndex → timestamp de première entrée. Persiste entre les renders,
  // et par séance dans localStorage (hydraté au 1er render de chaque séance).
  const reachedAt = useRef<Map<number, number>>(new Map());
  const hydratedKey = useRef<string | null>(null);

  const storageKey = startedAt ? `${STORAGE_PREFIX}${startedAt}` : null;
  if (storageKey && hydratedKey.current !== storageKey) {
    hydratedKey.current = storageKey;
    reachedAt.current = readSeance(storageKey); // remount pupitre → réels retrouvés
  }

  // Capture IDEMPOTENTE du 1er passage, pendant le render : `set` seulement si
  // absent (pattern lazy-ref toléré par React car sans effet observable
  // externe). Rend le « réel » visible dès le render courant, sans latence
  // d'un tick useEffect. Chaque nouveau franchissement (rare : 1 par partie)
  // est persisté pour survivre à un remount du pupitre.
  if (parts && startedAt && storageKey) {
    let captured = false;
    for (const p of parts) {
      if (index >= p.startIndex && !reachedAt.current.has(p.startIndex)) {
        reachedAt.current.set(p.startIndex, now);
        captured = true;
      }
    }
    if (captured) writeSeance(storageKey, reachedAt.current);
  }

  if (!parts || parts.length === 0) return [];

  const sorted = [...parts].sort((a, b) => a.startIndex - b.startIndex);
  const currentPart = [...sorted].reverse().find((p) => index >= p.startIndex);

  return sorted.map((p) => {
    const ts = reachedAt.current.get(p.startIndex);
    const realMinCumulative =
      ts && startedAt ? Math.round((ts - startedAt) / 60000) : null;
    const deltaMin =
      realMinCumulative === null ? null : realMinCumulative - p.targetMinCumulative;
    return {
      label: p.label,
      targetMinCumulative: p.targetMinCumulative,
      realMinCumulative,
      deltaMin,
      current: currentPart?.startIndex === p.startIndex,
    };
  });
}
