/**
 * ScenePacing — pastille de tempo AU PUPITRE (V6.D), extraite pour garder
 * PresenterView modulaire (règle 23). Couleur du niveau (vert marge / ambre
 * bientôt la fin / rouge dépassé) + « écoulé / budget » en minutes. Rien si la
 * scène n'a pas de budget cible.
 */
import styled from "styled-components";

import { color, withOpacity } from "@/shared/design-tokens/color";
import { px } from "@/shared/design-tokens/scale";
import { radius } from "@/shared/design-tokens/spacing";

import type { ScenePacing as ScenePacingData } from "./scene-pacing";

const LEVEL_COLOR = {
  ok: color.success,
  warn: color.secondary,
  over: color.error,
} as const;

const LEVEL_LABEL = {
  ok: "dans les temps",
  warn: "bientôt la fin",
  over: "temps dépassé",
} as const;

const Badge = styled.span<{ $level: "ok" | "warn" | "over" }>`
  display: inline-flex;
  align-items: center;
  gap: ${px(8)};
  padding: ${px(5)} ${px(12)};
  border-radius: ${radius.sm};
  font-size: ${px(15)};
  font-weight: 700;
  color: ${({ $level }) => LEVEL_COLOR[$level]};
  background: ${({ $level }) => withOpacity(LEVEL_COLOR[$level], 0.14)};
  font-variant-numeric: tabular-nums;
`;

interface ScenePacingProps {
  pacing: ScenePacingData | null;
}

export function ScenePacing({ pacing }: ScenePacingProps) {
  if (!pacing) return null;
  const usedMin = Math.floor(pacing.elapsedSec / 60);
  const usedSec = Math.floor(pacing.elapsedSec % 60);
  const budgetMin = Math.round(pacing.targetSec / 60);
  return (
    <Badge
      $level={pacing.level}
      role="status"
      aria-label={`Tempo de la scène : ${LEVEL_LABEL[pacing.level]}`}
    >
      ⏱ {LEVEL_LABEL[pacing.level]} · {usedMin}′
      {String(usedSec).padStart(2, "0")}″ / {budgetMin}′
    </Badge>
  );
}
