/**
 * Pacing par scène (V6.D) — indicateur de tempo AU PUPITRE : la scène courante
 * a-t-elle un budget de temps (`scene.targetMinutes`) et l'orateur est-il dans
 * les temps ? Vert (marge) → ambre (bientôt la fin) → rouge (dépassé). Aide
 * l'orateur à tenir son minutage scène par scène (au-delà du chrono total et
 * des parties — use-rehearsal-timer).
 */
import { useRef } from "react";

export type PacingLevel = "ok" | "warn" | "over";

/** Niveau de tempo depuis le temps écoulé sur la scène vs son budget (s). */
export function pacingLevel(
  elapsedSec: number,
  targetSec: number,
): PacingLevel | null {
  if (!targetSec || targetSec <= 0) return null;
  const ratio = elapsedSec / targetSec;
  if (ratio <= 0.8) return "ok";
  if (ratio <= 1.0) return "warn";
  return "over";
}

export interface ScenePacing {
  level: PacingLevel;
  elapsedSec: number;
  targetSec: number;
}

/**
 * Suit le temps passé sur la scène courante et en dérive le niveau de tempo.
 * `now` est l'horloge (ms) qui tique déjà dans la vue présentateur (pas de 2ᵉ
 * minuteur). Retourne null si la scène n'a pas de budget cible.
 */
export function useScenePacing(
  index: number,
  targetMinutes: number | undefined,
  now: number,
): ScenePacing | null {
  const enteredAtRef = useRef(now);
  const prevIndexRef = useRef(index);
  if (prevIndexRef.current !== index) {
    prevIndexRef.current = index;
    enteredAtRef.current = now; // nouvelle scène → on repart du temps courant
  }
  if (!targetMinutes || targetMinutes <= 0) return null;
  const elapsedSec = Math.max(0, (now - enteredAtRef.current) / 1000);
  const targetSec = targetMinutes * 60;
  const level = pacingLevel(elapsedSec, targetSec);
  if (!level) return null;
  return { level, elapsedSec, targetSec };
}
