/**
 * Analytics & Logging Utilitaire
 *
 * Système de tracking côté client pour:
 * - Événements utilisateur (clics, navigation)
 * - Temps passé sur les étapes
 * - Erreurs frontend
 * - Performance (Web Vitals)
 *
 * Compatible avec:
 * - Console (dev)
 * - Google Analytics 4 (si configuré)
 * - Backend custom (si endpoint configuré)
 */

import { logger } from "@/shared/utils/logger";
import { getRawSessionItem } from "@/shared/utils/storage";

// ============================================================================
// Types
// ============================================================================

type AnalyticsEventCategory =
  | "consultation_prep"
  | "consultation_tracker"
  | "payment"
  | "navigation"
  | "error"
  | "performance"
  | "engagement"
  | "onboarding"
  | "help_center"
  | "quotes"
  | "prestation_wizard"
  | "priorities_cockpit"
  | "tasks"
  | "operations"
  /* Le forum public : ce que les auteurs font des masques de la relecture
     (2026-09-12) — des comptes par nature, jamais un extrait. */
  | "forum"
  | "legal-deadlines"
  | "maitrise-active"
  | "kyc"
  | "presentation"
  /* Le SMS conversationnel (2026-09-16) : un fil ouvert, une réponse écrite —
     des comptes et des délais, jamais un extrait. */
  | "sms-conversationnel"
  // Categories migrees vers le hub (ex-call-sites _paq/gtag directs 2026-06-15) —
  // strings Matomo EXACTES preservees (anti-perte de donnees). Cf
  // instant-hero.copy.ts / ActivityDiagnosticPage.tsx / RagPrefsSettings.tsx.
  | "instant_landing"
  | "activity-development"
  | "RagV3Prefs";

export interface AnalyticsEvent {
  /** Catégorie de l'événement */
  category: AnalyticsEventCategory;
  /** Action effectuée */
  action: string;
  /** Label optionnel pour détailler l'action */
  label?: string;
  /** Valeur numérique optionnelle */
  value?: number;
  /** Données supplémentaires */
  metadata?: Record<string, unknown>;
}

interface PageViewEvent {
  /** Chemin de la page */
  path: string;
  /** Titre de la page */
  title?: string;
  /** Référent */
  referrer?: string;
}

interface TimingEvent {
  /** Catégorie (ex: "consultation_tracker") */
  category: string;
  /** Variable mesurée (ex: "step_duration") */
  variable: string;
  /** Durée en millisecondes */
  time: number;
  /** Label optionnel */
  label?: string;
}

export interface ErrorEvent {
  /** Message d'erreur */
  message: string;
  /** Stack trace */
  stack?: string;
  /** Composant source */
  componentStack?: string;
  /** URL où l'erreur s'est produite */
  url: string;
  /** Ligne (si disponible) */
  line?: number;
  /** Colonne (si disponible) */
  column?: number;
}

// ============================================================================
// Configuration
// ============================================================================

interface AnalyticsConfig {
  /** Activer le logging console (dev) */
  debug: boolean;
  /** Endpoint backend pour les analytics */
  backendEndpoint?: string;
  /** ID Google Analytics 4 */
  ga4Id?: string;
  /** Taille max du batch avant envoi */
  batchSize: number;
  /** Intervalle de flush (ms) */
  flushInterval: number;
}

const defaultConfig: AnalyticsConfig = {
  debug: false, // Disabled to reduce console noise (was: import.meta.env.DEV)
  backendEndpoint: import.meta.env.VITE_ANALYTICS_ENDPOINT,
  ga4Id: import.meta.env.VITE_GA4_ID,
  batchSize: 10,
  flushInterval: 30000, // 30 secondes
};

// ============================================================================
// Analytics Class
// ============================================================================

class Analytics {
  private static readonly MAX_QUEUE_SIZE = 500;
  private config: AnalyticsConfig;
  private eventQueue: AnalyticsEvent[] = [];
  private flushTimer: NodeJS.Timeout | null = null;
  private sessionId: string;

  constructor(config: Partial<AnalyticsConfig> = {}) {
    this.config = { ...defaultConfig, ...config };
    this.sessionId = this.generateSessionId();

    // Démarrer le timer de flush
    this.startFlushTimer();

    // Flush avant de quitter la page
    if (typeof window !== "undefined") {
      window.addEventListener("beforeunload", () => this.flush());
      window.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "hidden") {
          this.flush();
        }
      });
    }
  }

  private generateSessionId(): string {
    return `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }

  private startFlushTimer(): void {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
    }
    this.flushTimer = setInterval(
      () => this.flush(),
      this.config.flushInterval,
    );
  }

  /**
   * Envoyer les événements en attente
   */
  async flush(): Promise<void> {
    if (this.eventQueue.length === 0) {
      return;
    }

    const events = [...this.eventQueue];
    this.eventQueue = [];

    // Log en console (dev)
    if (this.config.debug) {
      logger.group("[Analytics] Flushing events");
      events.forEach((e) => logger.debug("[Analytics] Event:", e));
      logger.groupEnd();
    }

    // Envoyer au backend
    if (this.config.backendEndpoint) {
      try {
        await fetch(this.config.backendEndpoint, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            sessionId: this.sessionId,
            events,
            timestamp: Date.now(),
          }),
          // Utiliser keepalive pour les requêtes beforeunload
          keepalive: true,
        });
      } catch (error) {
        // Remettre les événements dans la queue en cas d'erreur, mais limiter à MAX_QUEUE_SIZE
        this.eventQueue = [...events, ...this.eventQueue].slice(
          0,
          Analytics.MAX_QUEUE_SIZE,
        );
        if (this.config.debug) {
          logger.error("[Analytics] Failed to send events:", error);
        }
      }
    }

    // Envoyer à GA4
    if (
      this.config.ga4Id &&
      typeof window !== "undefined" &&
      (window as unknown as { gtag?: (...args: unknown[]) => void }).gtag
    ) {
      const gtag = (window as unknown as { gtag: (...args: unknown[]) => void })
        .gtag;
      events.forEach((event) => {
        gtag("event", event.action, {
          event_category: event.category,
          event_label: event.label,
          value: event.value,
          ...event.metadata,
        });
      });
    }

    // Envoyer a Matomo (double-write — _paq est initialise par matomo-init.js).
    // Tous les events des helpers (analytics.track, quotesAnalytics, trackerAnalytics,
    // onboardingAnalytics, helpCenterAnalytics, bookingFunnelAnalytics) passent par
    // ici, donc cette boucle couvre TOUTES les sources de tracking front.
    //
    // ATTENTION DOUBLONS : platformAnalytics.ts (services/analytics/) push aussi
    // certains events business (booking_completed, signup_completed). Pour eviter
    // les doublons cote Matomo, NE PAS appeler analytics.track() avec un event
    // deja emis par platformAnalytics. Convention : platformAnalytics gere les
    // events "business critical / KPI" (PlatformEventType union), analytics.ts
    // gere les events UX/parcours (consultation_tracker, navigation, etc.).
    //
    // Cf ADR-027 + front/src/shared/utils/matomoProvider.ts.
    if (typeof window !== "undefined") {
      const paq = (window as unknown as { _paq?: unknown[] })._paq;
      if (Array.isArray(paq)) {
        // Re-pousser dim #6 appEnv (action-scope) avant chaque batch — les events
        // suivants seront automatiquement dimension'es. Sans ca, les events emis
        // depuis flush() perdent la dimension app-mode (matomo-init.js ne la
        // re-pousse pas a chaque event).
        const host =
          typeof window.location !== "undefined"
            ? window.location.hostname
            : "";
        let appMode = "client";
        if (host.indexOf("avocat.") === 0) appMode = "lawyer";
        else if (host.indexOf("admin.") === 0) appMode = "admin";
        else if (host.indexOf("me-") === 0) appMode = "minisite";
        paq.push(["setCustomDimension", 6, appMode]);

        events.forEach((event) => {
          const args: unknown[] = ["trackEvent", event.category, event.action];
          if (event.label !== undefined) args.push(event.label);
          if (event.value !== undefined) args.push(event.value);
          paq.push(args);
        });
      }
    }
  }

  /**
   * Tracker un événement
   */
  track(event: AnalyticsEvent): void {
    const enrichedEvent = {
      ...event,
      timestamp: Date.now(),
      sessionId: this.sessionId,
      url: typeof window !== "undefined" ? window.location.href : "",
    };

    this.eventQueue.push(enrichedEvent);

    // Flush si la queue est pleine
    if (this.eventQueue.length >= this.config.batchSize) {
      this.flush();
    }
  }

  /**
   * Tracker une page vue
   */
  pageView(event: PageViewEvent): void {
    this.track({
      category: "navigation",
      action: "page_view",
      label: event.path,
      metadata: {
        title: event.title,
        referrer: event.referrer || document.referrer,
      },
    });
  }

  /**
   * Tracker une durée
   */
  timing(event: TimingEvent): void {
    this.track({
      category: event.category as AnalyticsEventCategory,
      action: "timing",
      label: event.variable,
      value: event.time,
      metadata: {
        label: event.label,
      },
    });
  }

  /**
   * Tracker une erreur
   */
  error(event: ErrorEvent): void {
    this.track({
      category: "error",
      action: "error",
      label: event.message,
      metadata: {
        stack: event.stack,
        componentStack: event.componentStack,
        url: event.url,
        line: event.line,
        column: event.column,
      },
    });
  }

  /**
   * Mesurer le temps passé sur une étape
   */
  startStepTimer(stepName: string): () => void {
    const startTime = Date.now();

    return () => {
      const duration = Date.now() - startTime;
      this.timing({
        category: "consultation_tracker",
        variable: "step_duration",
        time: duration,
        label: stepName,
      });
    };
  }
}

