/**
 * Prestation wizard funnel analytics.
 *
 * Suit le parcours de creation/edition d'une prestation pour mesurer :
 *   - Taux d'abandon par etape (Forrester 2024 : cliff a 7 champs ; cf
 *     audit prestations 2026-05-04 -> Phase B Express/Avance toggle)
 *   - Adoption du mode Express vs Avance
 *   - Templates les plus utilises (vs creation 100% personnalisee)
 *   - Duree moyenne par type de prestation
 *
 * Categorie Matomo : `prestation_wizard`. Toutes les actions sont prefixees
 * `wizard.` pour faciliter le filtrage en dashboard.
 *
 * Usage typique :
 *   prestationWizardAnalytics.wizardOpened(serviceType, templateId);
 *   prestationWizardAnalytics.stepEntered(serviceType, 'pricing_payment', 2);
 *   prestationWizardAnalytics.advancedModeToggled(true);
 *   prestationWizardAnalytics.wizardCompleted(serviceType, planId);
 *   prestationWizardAnalytics.wizardAbandoned(serviceType, 'pricing_payment');
 */
export const prestationWizardAnalytics = {
  /** Drawer de creation ouvert (avant choix template) */
  drawerOpened(): void {
    analytics.track({
      category: "prestation_wizard",
      action: "drawer.opened",
    });
  },

  /** Avocat a clique sur une card de type prestation (consultation/mission/...) */
  typeSelected(serviceType: string): void {
    analytics.track({
      category: "prestation_wizard",
      action: "type.selected",
      label: serviceType,
    });
  },

  /** Wizard ouvert (apres choix type + eventuel template) */
  wizardOpened(serviceType: string, templateId?: string): void {
    analytics.track({
      category: "prestation_wizard",
      action: "wizard.opened",
      label: serviceType,
      metadata: { templateId: templateId ?? "custom" },
    });
  },

  /** Avocat entre dans une etape du wizard (presentation/details/pricing/...) */
  stepEntered(serviceType: string, step: string, stepIndex: number): void {
    analytics.track({
      category: "prestation_wizard",
      action: "step.entered",
      label: `${serviceType}.${step}`,
      value: stepIndex,
    });
  },

  /** Avocat valide une etape (clique Suivant et passe la validation) */
  stepCompleted(serviceType: string, step: string, stepIndex: number): void {
    analytics.track({
      category: "prestation_wizard",
      action: "step.completed",
      label: `${serviceType}.${step}`,
      value: stepIndex,
    });
  },

  /** Toggle Express/Avance sur StepPricingPayment (Pattern 2 audit 2026-05-04) */
  advancedModeToggled(enabled: boolean): void {
    analytics.track({
      category: "prestation_wizard",
      action: "advanced_mode.toggled",
      label: enabled ? "on" : "off",
    });
  },

  /** Wizard ferme avant submit (cleanup, abandoned, suspended-drawer) */
  wizardAbandoned(serviceType: string, lastStep: string): void {
    analytics.track({
      category: "prestation_wizard",
      action: "wizard.abandoned",
      label: `${serviceType}.${lastStep}`,
    });
  },

  /** Wizard submit avec succes (plan cree cote backend) */
  wizardCompleted(serviceType: string, planId: string): void {
    analytics.track({
      category: "prestation_wizard",
      action: "wizard.completed",
      label: serviceType,
      metadata: { planId },
    });
  },

  /** Plan modifie via PrestationEditDrawer (post-creation) */
  planEdited(serviceType: string, planId: string, fieldChanged: string): void {
    analytics.track({
      category: "prestation_wizard",
      action: "plan.edited",
      label: `${serviceType}.${fieldChanged}`,
      metadata: { planId },
    });
  },
};

