/**
 * Envoie un event booking directement vers POST /back/api/analytics/events
 * (BookingAnalyticsController). Fire-and-forget, aucun blocage UI.
 */
function sendBookingEvent(
  eventType: string,
  fields: Record<string, unknown> = {},
): void {
  // UN `lawyerId` VIDE N'EST PAS UN ÉVÉNEMENT (2026-08-25). Les appelants le
  // tirent de `bookingInfo?.lawyer.id || ""` : avant chargement, il vaut la
  // chaîne vide. Le DTO back la refuse (`@IsUUID()`), et le `.catch` ci-dessous
  // avalerait ce 400 — l'étape serait perdue SANS un mot. On s'abstient plutôt
  // que d'émettre ce qui sera jeté.
  if ("lawyerId" in fields && !fields.lawyerId) return;
  const sid = getRawSessionItem("analytics_session_id") || undefined;
  // UN TRACEUR NE CASSE JAMAIS LE PARCOURS QU'IL OBSERVE (2026-08-25).
  // `fetch(...).catch()` suppose que `fetch` rend une promesse. Quand ce n'est
  // pas le cas — surcharge par une extension, un bloqueur, un banc qui le
  // mocke sans valeur de retour — le `.catch` lève sur `undefined` et l'appel
  // remonte jusqu'à l'ErrorBoundary : le tunnel de RÉSERVATION tombe pour un
  // événement de mesure. Mesuré ici, 41 bancs rouges d'un coup. Tant que ces
  // appels étaient un no-op, ce risque n'existait pas ; les brancher le crée.
  try {
    const envoi = fetch("/back/api/analytics/events", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        events: [
          {
            eventType,
            timestamp: new Date().toISOString(),
            sessionId: sid,
            referrer: document.referrer || undefined,
            ...fields,
          },
        ],
      }),
      keepalive: true,
    });
    if (envoi && typeof envoi.catch === "function") envoi.catch(() => {});
  } catch {
    /* silence VOULU : la mesure est perdue, le parcours continue. */
  }
}

/**
 * Track le funnel de prise de rendez-vous sur un profil public avocat.
 * Mappe vers les eventTypes backend : booking_started, booking_plan_selected, etc.
 *
 * ⚠ DÉBRANCHÉ — ZÉRO APPELANT DE PRODUCTION (mesuré le 2026-08-24). Deux
 * occurrences dans tout le front : cette définition, et une mention en
 * commentaire. Conséquence : l'entonnoir avocat (`getFunnel`) n'a plus qu'un
 * producteur actif, le SEEDER DE DÉMO — un vrai avocat voit un zéro qui ne
 * peut pas monter, indiscernable d'un « pas encore d'activité ».
 *
 * NON SUPPRIMÉ, délibérément : c'est le seul tracker de ce tunnel qui porte un
 * `lawyerId`, et le rebrancher demande d'appeler ses méthodes depuis le
 * parcours du profil public, pas de le réécrire. Il lui manquerait une méthode
 * pour la 7e étape (`booking_completed`).
 *
 * LES DEUX AUTRES CHEMINS ET LEURS PIÈGES — `trackBookingEvent` (no-op RGPD
 * volontaire) et `platform_analytics_events` (où `booking_completed` sert
 * l'attribution de contenu, sans `lawyerId`) : le détail mesuré vit dans
 * `roadmap/auvents-program/CHECKLIST.md`, au finding P0 du tunnel. Le lire
 * AVANT de rebrancher quoi que ce soit : quatre analyses fausses s'y sont
 * succédé.
 */
export const bookingFunnelAnalytics = {
  /** Etape atteinte — mappe stepName vers eventType backend */
  stepViewed(lawyerId: string, step: string, lawyerName?: string): void {
    const stepToEvent: Record<string, string> = {
      "profile-plan": "booking_started",
      "contact-info": "booking_contact_filled",
    };
    const eventType = stepToEvent[step];
    if (eventType) {
      sendBookingEvent(eventType, { lawyerId, lawyerName, stepName: step });
    }
  },

  /** Prestation selectionnee */
  planSelected(
    lawyerId: string,
    planId: string,
    planType: string,
    lawyerName?: string,
  ): void {
    sendBookingEvent("booking_plan_selected", {
      lawyerId,
      lawyerName,
      planId,
      source: planType,
    });
  },

  /** Creneau choisi */
  slotSelected(
    lawyerId: string,
    planId: string | null,
    lawyerName?: string,
  ): void {
    sendBookingEvent("booking_date_selected", { lawyerId, lawyerName, planId });
  },

  /** Paiement initie (Stripe Checkout) */
  paymentInitiated(
    lawyerId: string,
    planId: string | null,
    amountCents?: number,
    lawyerName?: string,
  ): void {
    sendBookingEvent("booking_payment_started", {
      lawyerId,
      lawyerName,
      planId,
      amount: amountCents,
    });
  },

  /** Paiement confirme */
  paymentSuccess(
    lawyerId: string,
    planId: string | null,
    amountCents?: number,
    lawyerName?: string,
  ): void {
    sendBookingEvent("booking_payment_success", {
      lawyerId,
      lawyerName,
      planId,
      amount: amountCents,
    });
  },

  /**
   * Rendez-vous PRIS — le seul des sept maillons de `getBookingFunnel` qui
   * n'avait aucun émetteur (2026-08-25) : il affichait 0 pour tout avocat.
   *
   * Piège du sujet : DEUX tables portent ce nom pour des usages disjoints.
   * `platform_analytics_events` compte des attributions de CONTENU (12 025
   * lignes, `lawyerId` absent des 12 025) ; ici ce sont des réservations,
   * scopées par avocat.
   */
  completed(
    lawyerId: string,
    planId: string | null,
    lawyerName?: string,
  ): void {
    sendBookingEvent("booking_completed", { lawyerId, lawyerName, planId });
  },

  /** Booking abandonne (fermeture / navigation avant paiement) */
  abandoned(lawyerId: string, lastStep: string, lawyerName?: string): void {
    sendBookingEvent("booking_abandoned", {
      lawyerId,
      lawyerName,
      stepName: lastStep,
    });
  },
};

