/**
 * usePresentationRuntime — instrumentation runtime du shell : analytics par
 * scène (tous modes) + modes AUTO-GUIDÉS (V6.A solo + V6.D kiosk). Extrait du
 * shell (règle 22/23) : il ne garde qu'un appel de hook et consomme le retour.
 *
 * - Analytics : funnel entrée/sortie par scène → Matomo souverain, désactivé en
 *   présentateur (pupitre + audience synchronisés → seule l'audience trace).
 * - Solo (`?mode=solo`, envoi async) : auto-avance jusqu'à la dernière scène du
 *   flux principal, puis s'arrête.
 * - Kiosk (`?mode=kiosk`, borne/salon) : idem + repart au début (boucle).
 * - Toute reprise de contrôle manuelle met en pause (`pauseAuto`).
 */
import { useMemo, useState } from "react";

import { SOLO_DEFAULT_DWELL_MS, useAutoAdvance } from "./use-auto-advance";
import { useSceneAnalytics } from "./use-scene-analytics";
import type { PresentationPlaybackMode } from "./presentation-analytics";
import type {
  BlackoutMode,
  PresentationScene,
} from "./presentation-definition";

/** Mode auto-guidé demandé dans l'URL (`?mode=solo|kiosk`), sinon null. */
export function readPlaybackParam(): "solo" | "kiosk" | null {
  const m = new URLSearchParams(window.location.search).get("mode");
  return m === "solo" || m === "kiosk" ? m : null;
}

/** Un mode auto-guidé est demandé → pas d'accueil (standby) bloquant. */
export function autoGuideRequested(): boolean {
  return readPlaybackParam() !== null;
}

interface RuntimeArgs {
  scenes: PresentationScene[];
  scene: PresentationScene;
  index: number;
  step: number;
  sceneFragments: number;
  total: number;
  mainCount: number;
  isPresenter: boolean;
  channelId: string;
  standby: boolean;
  blackout: BlackoutMode | null;
  forward: () => void;
  /** Retour au début (kiosk : boucle). */
  restart: () => void;
}

export interface PresentationRuntime {
  /** Un mode auto-guidé (solo ou kiosk) est actif. */
  isAutoGuided: boolean;
  playbackMode: PresentationPlaybackMode;
  autoPaused: boolean;
  pauseAuto: () => void;
  resumeAuto: () => void;
  atMainEnd: boolean;
  dwellMs: number;
  stepKey: string;
}

export function usePresentationRuntime({
  scenes,
  scene,
  index,
  step,
  sceneFragments,
  total,
  mainCount,
  isPresenter,
  channelId,
  standby,
  blackout,
  forward,
  restart,
}: RuntimeArgs): PresentationRuntime {
  const param = useMemo(
    () => (isPresenter ? null : readPlaybackParam()),
    [isPresenter],
  );
  const playbackMode: PresentationPlaybackMode = param ?? "live";
  const isAutoGuided = param !== null;
  const isKiosk = param === "kiosk";
  const [autoPaused, setAutoPaused] = useState(false);

  // Analytics par scène (tous modes ; jamais en présentateur → zéro double compte).
  useSceneAnalytics({
    deckId: channelId,
    scenes,
    index,
    mode: playbackMode,
    enabled: !isPresenter,
    mainCount,
  });

  // Dernière scène du flux principal atteinte (les annexes restent hors auto).
  const atMainEnd =
    !scene.appendix &&
    step >= sceneFragments &&
    (index + 1 >= total || Boolean(scenes[index + 1]?.appendix));
  const dwellMs = scene.soloDwellMs ?? SOLO_DEFAULT_DWELL_MS;
  const stepKey = `${index}-${step}`;

  useAutoAdvance({
    enabled: isAutoGuided,
    paused: autoPaused || standby || blackout !== null,
    atEnd: atMainEnd,
    dwellMs,
    stepKey,
    advance: forward,
    loop: isKiosk,
    restart,
  });

  return {
    isAutoGuided,
    playbackMode,
    autoPaused,
    pauseAuto: () => setAutoPaused(true),
    resumeAuto: () => setAutoPaused(false),
    atMainEnd,
    dwellMs,
    stepKey,
  };
}
