/**
 * Synchronisation audience ↔ présentateur par BroadcastChannel (extrait du
 * shell — ratchet règle 23, audit 2026-07-05).
 *
 * Protocole « hello » (anti-reset au mount, P1 d'audit prouvé en runtime) :
 *  - un pair qui MONTE ne diffuse jamais son état initial — il envoie
 *    `{hello}` et les pairs déjà présents répondent leur état courant
 *    (rouvrir le pupitre en pleine séance se CALE sur la scène en cours au
 *    lieu de renvoyer l'écran projeté à la scène 1) ;
 *  - défense en profondeur : un état de REPOS ({0,0,null} — onglet oublié à
 *    l'accueil qui répond à un hello) n'écrase jamais une séance démarrée
 *    (Home volontaire garde startedAt ≠ null, donc {0,0,null} n'est jamais
 *    légitime à imposer).
 */
import { useEffect, useRef } from "react";

import type { PresentationSyncState } from "./presentation-definition";

export function usePresentationSync(
  channelId: string,
  state: PresentationSyncState,
  applyRemote: (remote: PresentationSyncState) => void,
) {
  const channelRef = useRef<BroadcastChannel | null>(null);
  // Miroir de l'état courant pour répondre à un `hello` (le onmessage est
  // une closure du mount — sans ref il répondrait un état STALE).
  const syncRef = useRef<PresentationSyncState>(state);
  syncRef.current = state;
  const published = useRef(false);
  // Anti-écho par VALEUR (P2 d'audit 2026-07-05) : un état appliqué depuis le
  // channel ne doit pas être rediffusé par le re-render qui suit. L'ancien
  // flag booléen ratait sa fenêtre (remis à false de façon synchrone alors
  // que l'effet de publication court après le re-render). Ici : mémoriser le
  // dernier état REÇU et taire la publication tant qu'elle lui est identique ;
  // toute navigation locale produit un état différent → publiée, et efface la
  // mémoire (l'anti-écho ne vaut que pour le re-render post-application).
  const lastRemote = useRef<PresentationSyncState | null>(null);
  const applyRef = useRef(applyRemote);
  applyRef.current = applyRemote;

  useEffect(() => {
    const ch = new BroadcastChannel(channelId);
    channelRef.current = ch;
    ch.onmessage = (
      e: MessageEvent<PresentationSyncState | { hello: true }>,
    ) => {
      if ("hello" in e.data) {
        ch.postMessage(syncRef.current);
        return;
      }
      const { index: i, step: s, startedAt: t } = e.data;
      // L'idle-check porte sur la POSITION seule (un état de repos avec un
      // blackout n'a pas de sens réel) — blackout voyage en passager.
      const incomingIdle = i === 0 && s === 0 && t === null;
      const cur = syncRef.current;
      const started = cur.index > 0 || cur.step > 0 || cur.startedAt !== null;
      if (incomingIdle && started) return;
      lastRemote.current = { index: i, step: s, startedAt: t, blackout: e.data.blackout ?? null };
      applyRef.current(e.data);
    };
    ch.postMessage({ hello: true });
    return () => ch.close();
  }, [channelId]);

  useEffect(() => {
    // Première exécution = état initial du mount : ne pas l'imposer aux
    // pairs (protocole hello).
    if (!published.current) {
      published.current = true;
      return;
    }
    const cur = syncRef.current;
    const lr = lastRemote.current;
    if (
      lr &&
      lr.index === cur.index &&
      lr.step === cur.step &&
      lr.startedAt === cur.startedAt &&
      (lr.blackout ?? null) === (cur.blackout ?? null)
    )
      return; // écho d'un état reçu — ne pas rediffuser
    lastRemote.current = null;
    channelRef.current?.postMessage(cur);
  }, [state.index, state.step, state.startedAt, state.blackout]);
}
