/**
 * Multi-écran « Envoyer sur le projecteur » (moteur V1.c, GO user 2026-07-05).
 *
 * Window Management API — findings recherche VÉRIFIÉS 3-0 (MDN + web.dev +
 * spec W3C, use case « slideshow » explicite) :
 *  - `window.screen.isExtended` : détection multi-écran SANS prompt ;
 *  - `window.getScreenDetails()` : énumération des écrans (prompt de
 *    permission `window-management` au 1er appel, HTTPS requis) ;
 *  - `element.requestFullscreen({ screen })` : plein écran CIBLÉ sur le
 *    projecteur — résout l'impossibilité historique de choisir l'écran.
 *
 * Contrainte vérifiée : Chromium 100+ UNIQUEMENT (jamais Firefox/Safari,
 * non polyfillable) → PROGRESSIVE ENHANCEMENT strict : API absente ou
 * mono-écran → `projectorAvailable=false`, le shell n'affiche rien et le
 * fallback universel (F + glisser la fenêtre) reste intact.
 *
 * Point empirique restant (répétition, 2 écrans réels) : le plein écran
 * externe survit-il au focus sur la fenêtre présentateur ? (non documenté
 * de façon fiable — la garde fullscreen affiche sa pill si ça saute.)
 */
import { useCallback, useEffect, useState } from "react";
import type { RefObject } from "react";

type ScreenDetailedLike = { isPrimary?: boolean };
type ScreenDetailsLike = {
  currentScreen?: ScreenDetailedLike;
  screens: ScreenDetailedLike[];
};
type WindowWithScreenDetails = Window & {
  getScreenDetails?: () => Promise<ScreenDetailsLike>;
};
type ScreenWithExtended = Screen & { isExtended?: boolean };

function computeAvailable(): boolean {
  const w = window as WindowWithScreenDetails;
  const s = window.screen as ScreenWithExtended;
  return typeof w.getScreenDetails === "function" && s.isExtended === true;
}

export function useProjector(stageRef: RefObject<HTMLElement | null>) {
  const [projectorAvailable, setProjectorAvailable] = useState(false);

  useEffect(() => {
    setProjectorAvailable(computeAvailable());
    // `screenschange` vit sur ScreenDetails (permission requise) — pour la
    // simple DISPONIBILITÉ du bouton, re-check sans prompt au retour de focus
    // (cas réel jour J : projecteur branché après le lancement du deck).
    const recheck = () => setProjectorAvailable(computeAvailable());
    window.addEventListener("focus", recheck);
    return () => window.removeEventListener("focus", recheck);
  }, []);

  /** Plein écran du stage SUR l'écran externe. Fallback : fullscreen simple. */
  const sendToProjector = useCallback(async () => {
    const stage = stageRef.current;
    if (!stage) return;
    try {
      const w = window as WindowWithScreenDetails;
      const details = await w.getScreenDetails!(); // prompt permission au 1er appel
      const target =
        details.screens.find(
          (s) => s !== details.currentScreen && s.isPrimary === false,
        ) ??
        details.screens.find((s) => s !== details.currentScreen) ??
        null;
      await (
        stage.requestFullscreen as (opts?: {
          screen?: ScreenDetailedLike;
        }) => Promise<void>
      )(target ? { screen: target } : undefined);
    } catch {
      // Permission refusée / API capricieuse → fullscreen classique, jamais
      // d'erreur visible en séance.
      await stage.requestFullscreen().catch(() => undefined);
    }
  }, [stageRef]);

  return { projectorAvailable, sendToProjector };
}
