/**
 * useSceneAnalytics — funnel de progression par scène (presentation-engine V6.A,
 * « conversion async traçable »).
 *
 * POURQUOI. Quand on envoie le deck à un prospect par lien (mode `solo`), on ne
 * sait rien de ce qu'il en fait. Ce hook émet, pour chaque scène, une entrée +
 * une sortie horodatée (dwell) vers Matomo souverain : on voit alors où il
 * décroche (scène quittée en < 1 s = pas lue), ce qui l'accroche (dwell long),
 * et le taux de complétion. Le même instrument mesure une séance en salle
 * (mode `live`) — la dimension `mode` sépare les deux.
 *
 * GARDE-FOUS.
 * - Souverain : passe par le hub `presentationAnalytics` → Matomo self-hosté EU.
 * - Pas de double compte : `enabled=false` sur la vue présentateur (pupitre et
 *   audience sont synchronisés — seule l'audience/le projeté trace).
 * - Dwell de la DERNIÈRE scène capturé même quand l'onglet se ferme : `pagehide`
 *   déclenche le flush, et le hub `analytics` poste en `keepalive`.
 * - Idempotent : une sortie de scène n'est émise qu'une fois (garde `settled`),
 *   qu'elle vienne d'un changement de scène, d'un `pagehide` ou du démontage.
 */
import { useEffect, useRef } from "react";

import { presentationAnalytics } from "./presentation-analytics";
import type { PresentationPlaybackMode } from "./presentation-analytics";
import type { PresentationScene } from "./presentation-definition";

interface SceneAnalyticsArgs {
  /** Identifiant du deck (channelId — stable, unique par présentation). */
  deckId: string;
  scenes: PresentationScene[];
  /** Index de la scène courante (piloté par le shell). */
  index: number;
  mode: PresentationPlaybackMode;
  /** false = ne trace pas (vue présentateur : évite le double compte). */
  enabled: boolean;
  /** Nombre de scènes du flux principal (hors appendix) — pour la complétion. */
  mainCount: number;
}

export function useSceneAnalytics({
  deckId,
  scenes,
  index,
  mode,
  enabled,
  mainCount,
}: SceneAnalyticsArgs): void {
  const enteredAtRef = useRef<number>(0);
  const currentRef = useRef<number | null>(null);
  const startedRef = useRef(false);
  const completedRef = useRef(false);
  // Vrai quand la sortie de la scène courante a déjà été émise (anti-doublon
  // entre changement de scène / pagehide / démontage).
  const settledRef = useRef(false);

  // Émet la sortie de la scène courante une seule fois.
  const emitLeave = useRef<() => void>(() => {});
  emitLeave.current = () => {
    if (settledRef.current || currentRef.current === null) return;
    const scene = scenes[currentRef.current];
    if (!scene) return;
    settledRef.current = true;
    presentationAnalytics.sceneLeave(
      deckId,
      mode,
      scene,
      currentRef.current,
      Date.now() - enteredAtRef.current,
    );
  };

  // Entrées / sorties au fil des changements de scène.
  useEffect(() => {
    if (!enabled) return;
    const scene = scenes[index];
    if (!scene) return;

    if (!startedRef.current) {
      startedRef.current = true;
      presentationAnalytics.deckStart(deckId, mode, mainCount);
    } else if (currentRef.current !== index) {
      emitLeave.current(); // sortie de la scène précédente
    }

    if (currentRef.current !== index) {
      currentRef.current = index;
      enteredAtRef.current = Date.now();
      settledRef.current = false;
      presentationAnalytics.sceneEnter(deckId, mode, scene, index);
    }

    // Complétion : dernière scène du flux principal atteinte (une seule fois).
    if (!completedRef.current && !scene.appendix && index === mainCount - 1) {
      completedRef.current = true;
      presentationAnalytics.deckComplete(deckId, mode, mainCount);
    }
  }, [enabled, index, deckId, mode, mainCount, scenes]);

  // Fermeture d'onglet / démontage : flush du dwell de la dernière scène.
  useEffect(() => {
    if (!enabled) return;
    const onHide = () => emitLeave.current();
    window.addEventListener("pagehide", onHide);
    return () => {
      window.removeEventListener("pagehide", onHide);
      emitLeave.current();
    };
  }, [enabled]);
}
