/**
 * Un glyphe de service — tracé dans un carré de 24, en trait, jamais rempli :
 * le trait des cartes de la couverture LinkedIn (`shared/config/services-de-la-marque.ts`).
 * Décoratif : le nom accessible appartient au bouton qui le porte.
 */
export function Glyphe({ trace }: { trace: string }) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
      <path
        d={trace}
        fill="none"
        stroke="currentColor"
        strokeWidth={1.7}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

/** Le glyphe du bouton de pause de la scène : deux barres, ou le triangle de la reprise. */
export function IconePause({ enPause }: { enPause: boolean }) {
  return (
    <svg viewBox="0 0 14 14" aria-hidden="true" focusable="false">
      {enPause ? (
        <path d="M3.5 2.2 11.5 7l-8 4.8z" fill="currentColor" />
      ) : (
        <path d="M3.5 2.5h2.4v9H3.5zM8.1 2.5h2.4v9H8.1z" fill="currentColor" />
      )}
    </svg>
  );
}
