import { getRuntimeEnv } from "./runtime-env";

export const Envs = {
  // Runtime-first (levier 2 cascade 2026-07-13) : window.__ENV (env.js posé
  // par l'entrypoint du container) prime, fallback import.meta.env (bakée au
  // build — comportement historique). PHASE 1 : le compose front n'injecte
  // AUCUNE de ces vars → __ENV vide → fallback partout = zéro changement.
  // PHASE 2 (bascule effective) : ajouter les vars au service front du
  // compose — pour STRIPE_PUBLISHABLE_KEY (money-path test vs live), une
  // validation paiement dédiée par env est OBLIGATOIRE avant (règle 42).
  CONTACT_EMAIL: getRuntimeEnv("VITE_CONTACT_EMAIL") ?? import.meta.env.VITE_CONTACT_EMAIL,
  BASE_API_URL: import.meta.env.VITE_BASE_API_URL,
  BASE_BACKEND_URL: getRuntimeEnv("VITE_BASE_BACKEND_URL") ?? import.meta.env.VITE_BASE_BACKEND_URL,

  // Fallback to Stripe test key to prevent crashes when not configured
  STRIPE_PUBLISHABLE_KEY: getRuntimeEnv("VITE_STRIPE_PUBLISHABLE_KEY") || import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY || 'pk_test_placeholder_key_not_functional',
  // minimum duration in minutes for a meeting to be considered completed
  // by default, sets to 10 minutes
  MINIMUM_MEETING_DURATION_MINUTES:
    Number(import.meta.env.VITE_MINIMUM_MEETING_DURATION_MINUTES) || 10,
  INVOICE_COMPANY_INFO:
    import.meta.env.VITE_INVOICE_COMPANY_INFO ||
    "MEDIANE, SAS au capital de 1 500,00 € – RCS Paris 929 452 969",
  ENV: import.meta.env.VITE_ENV || "development",
};

// Validate critical env vars at startup — missing vars indicate a misconfigured build
const REQUIRED_VARS: Array<[keyof typeof Envs, string]> = [
  ["BASE_BACKEND_URL", "API calls will fail"],
  ["STRIPE_PUBLISHABLE_KEY", "Payments will not work"],
];

if (import.meta.env.PROD) {
  for (const [key, impact] of REQUIRED_VARS) {
    if (!Envs[key]) {
      console.warn(`[ENV] Missing VITE_${key} — ${impact}`);
    }
  }
}

// VITE_ENV est injecté au build par la valeur `environment:` du job (build-image.yml
// → build-arg ENV → Dockerfile `VITE_ENV=${ENV}`). Les workflows passent les alias
// COURTS : deploy.prod → "prod", deploy.dev → "dev". En local
// (aucun build-arg) le fallback vaut "development". Les helpers ci-dessous DOIVENT
// donc accepter l'alias court ET la forme longue, sinon ils renvoient false sur
// l'environnement déployé correspondant (bug historique isProductionEnvironment :
// testait "production" alors que le build prod injecte "prod" — cf incident 2026-07-03).
// Un seul point de vérité par environnement, pas de comparaison `Envs.ENV === "..."`
// ad hoc ailleurs (divergence garantie). Détail : documentation/agent-rules/feature-flags-environments.md.

/**
 * Check if we're running in production environment (accepte "prod" et "production")
 */
export const isProductionEnvironment = (): boolean => {
  return Envs.ENV === "production" || Envs.ENV === "prod";
};

/**
 * Check if we're running in development environment (accepte "dev", "development", vide)
 *
 * ⚠️ VRAI SUR L'ÉTAGE DEV DÉPLOYÉ, PAS SEULEMENT SUR LE POSTE. `deploy.dev`
 * injecte `VITE_ENV=dev` au build de l'étage (avocat.dev.…), et cet alias est
 * accepté ici depuis le 2026-07-03. Pour un outil qui ne doit exister QUE sur
 * la machine d'un développeur, c'est `estPosteLocal()` qu'il faut lire.
 */
export const isDevelopmentEnvironment = (): boolean => {
  return Envs.ENV === "development" || Envs.ENV === "dev" || !Envs.ENV;
};

/**
 * Le front tourne-t-il sur le POSTE d'un développeur — et nulle part ailleurs ?
 *
 * Le critère n'est pas le nom d'environnement : le poste et l'étage dev
 * peuvent porter le même (`dev`), et `isDevelopmentEnvironment()` rend vrai
 * pour les deux. Le critère est la façon dont le front est SERVI : le poste
 * lance le serveur de dev de Vite (`npx vite`, `docker/frontend/Dockerfile.dev`),
 * tout étage sert un bundle construit (`npm run build`, `Dockerfile.prod`).
 * `import.meta.env.DEV` est vrai dans le premier cas, faux dans le second, et
 * ne dépend d'aucune variable qu'un déploiement pourrait mal poser.
 *
 * Vu le 2026-09-25 (cascade #1365) : le dock « Auto / Prod / Bêta », annoncé
 * « DEV LOCAL UNIQUEMENT », s'affichait sur l'étage dev par-dessus le logo du
 * menu. Le dock est retiré depuis le 2026-10-04 ; ses cas sur ce prédicat
 * vivent dans `__tests__/env.test.ts`.
 */
export const estPosteLocal = (): boolean => {
  return import.meta.env.DEV === true;
};
