import { Suspense, useCallback, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ReactNode } from "react";

import { SphereDeConnexions, type PoigneeDeLaSphere } from "@/shared/animations/scene/SphereDeConnexions";
import { MARQUE } from "@/shared/config/marque-du-produit";
import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";
import { nuit } from "@/shared/design-tokens/vitrine-de-nuit.tokens";
import { lazyWithRetry } from "@/shared/utils/lazy-with-retry";

import { Glyphe, IconePause } from "./Glyphe";
import {
  BoutonPause,
  Carte,
  CarteDetail,
  CarteTexte,
  CarteTitre,
  Centre,
  Couche,
  Disque,
  Halo,
  Libelle,
  Planete,
  Scene,
  Terme,
  Traits,
} from "./reseau.styles";
import { BATTEMENTS } from "./systeme.flux";
import { LIENS_EN_INDEX, NOEUDS_DU_RESEAU, type MesuresDeLaScene, mesurerLaScene } from "./systeme.reseau";
import type { EtatDuReseau, RegistreDuReseau } from "./reseau.types";
import { useAnimationDuReseau } from "./useAnimationDuReseau";

/**
 * ReseauDuCabinet — la scène animée du système du cabinet : les services en
 * planètes de verre, reliés par des filaments à la sphère de connexions que
 * traverse le nom de la marque, et le flux qui court entre eux.
 *
 * Croquis `charte-visuelle-juris-connect/croquis/2026-09-25-le-systeme-du-cabinet.md`.
 *
 * LA SCÈNE NE REND QU'UNE FOIS. Ses éléments sont posés par React, puis
 * l'horloge (`useAnimationDuReseau`) les déplace à chaque image. L'état React ne
 * change qu'au survol, à la pause et à chaque battement — pour le texte de la
 * carte.
 *
 * DEUX FORMES, choisies par la largeur de la SCÈNE : le système complet à partir
 * de 640 px, la vue de face compacte en dessous (`mesurerLaScene`).
 *
 * DEUX USAGES depuis le 2026-10-14 : la vitrine (le héros de la landing avocats,
 * interactive) et la planche de présentation (`interactif` faux) — la même
 * scène, mise à l'échelle d'un bloc par son cadre (`echelle`), sans plongée,
 * sans fiche, sans bouton de pause : l'orateur la pilote.
 */

/* Les fiches du survol et leurs textes se chargent à la première intention (`FichesDuSurvol.tsx`). */
const chargerLesFiches = () => import("./FichesDuSurvol");
const FichesDuSurvol = lazyWithRetry(chargerLesFiches);

const SANS_GESTE = () => undefined;

export function ReseauDuCabinet({
  reduit,
  plonge,
  onOuvrir,
  onIntention,
  onVoirTout,
  interactif = true,
  echelle = 1,
  battementPilote = null,
  enPause,
  dispersion = null,
  cadence = 1,
  terme,
  sansCarte = false,
}: {
  /** Mouvement réduit : tout en place d'emblée, rien ne tourne. */
  reduit: boolean;
  /** Un service est ouvert en plongée : le réseau recule et s'arrête. */
  plonge: IdServiceDeLaMarque | null;
  onOuvrir?: (id: IdServiceDeLaMarque, depuis: HTMLElement) => void;
  /** Un service est survolé ou focalisé : on s'apprête peut-être à l'ouvrir. */
  onIntention?: () => void;
  onVoirTout?: () => void;
  /**
   * Faux sur une planche de présentation : la scène se regarde, elle ne se
   * parcourt pas — aucun service ne s'ouvre, aucune fiche, aucun bouton de
   * pause, et la scène se lit d'un seul nom (une image) au lieu de douze
   * boutons dans l'ordre de tabulation de la salle.
   */
  interactif?: boolean;
  /** L'agrandissement de la scène à l'écran : sa mesure à l'écran est divisée
   *  par lui, et la sphère se dessine d'autant plus dense pour rester nette. */
  echelle?: number;
  /** Le battement demandé (planche pilotée) ; `null` : ils s'enchaînent seuls. */
  battementPilote?: number | null;
  /** La pause, tenue par l'appelant (planche) ; sinon le bouton de la scène. */
  enPause?: boolean;
  /** L'entrée dispersée d'une planche (README) ; `null` sur la landing. */
  dispersion?: { reliee: boolean } | null;
  /** La vitesse du flux des battements. */
  cadence?: number;
  /** Le contenu du nom central ; par défaut, le nom de la marque. */
  terme?: ReactNode;
  /** La carte du battement se tait : la planche qui le pilote dit le battement elle-même. */
  sansCarte?: boolean;
}) {
  const scene = useRef<HTMLDivElement>(null);
  const [mesures, setMesures] = useState<MesuresDeLaScene | null>(null);
  const mesuresRef = useRef<MesuresDeLaScene | null>(null);
  const [survole, setSurvole] = useState<number | null>(null);
  const [pauseLocale, setPauseLocale] = useState(false);
  const [battement, setBattement] = useState(-1);
  const pause = enPause ?? pauseLocale;

  const etat = useRef<EtatDuReseau>({
    survole: null,
    plonge: false,
    pause: false,
    parallaxe: { x: 0, y: 0 },
    battementPilote: null,
    dispersion: null,
    cadence: 1,
  });
  etat.current.survole = survole;
  etat.current.plonge = plonge !== null;
  etat.current.pause = pause;
  etat.current.battementPilote = battementPilote;
  etat.current.dispersion = dispersion;
  etat.current.cadence = cadence;

  /* Un registre recalculé au rechargement à chaud : un useRef garderait l'objet
     d'avant une modification, et un champ ajouté y manquerait (vu le
     2026-09-25 — la scène tombait sur un « current » d'undefined). */
  const registre = useMemo<RegistreDuReseau>(
    () => ({
      scene,
      planetes: [],
      filaments: [],
      liens: [],
      trainee: { current: null },
      tete: { current: null },
      degrade: { current: null },
      carte: { current: null },
      fil: { current: null },
      terme: { current: null },
      fiches: { current: null },
      sphere: { current: null },
    }),
    [],
  );

  const { redessiner } = useAnimationDuReseau({
    registre,
    etat,
    mesures: mesuresRef,
    reduit,
    onBattement: setBattement,
  });

  /* La scène se mesure : ses proportions sont fixes, sa largeur décide de tout.
     Dans SON repère : un cadre qui la met à l'échelle ne change pas sa
     composition, seulement sa taille à l'écran. */
  useLayoutEffect(() => {
    const el = scene.current;
    if (!el) return;
    const mesurer = () => {
      const { width, height } = el.getBoundingClientRect();
      if (width <= 0 || height <= 0) return;
      const m = mesurerLaScene(width / echelle, height / echelle);
      mesuresRef.current = m;
      setMesures((avant) =>
        avant && avant.largeur === m.largeur && avant.hauteur === m.hauteur ? avant : m,
      );
    };
    mesurer();
    const observateur = new ResizeObserver(mesurer);
    observateur.observe(el);
    return () => observateur.disconnect();
  }, [echelle]);

  /* Au mouvement réduit, l'horloge ne tourne pas : une image à chaque
     changement qui déplace quelque chose. */
  useLayoutEffect(() => {
    if (reduit) redessiner();
  }, [reduit, redessiner, mesures, survole, battementPilote, dispersion?.reliee]);

  /* La parallaxe suit la souris du VISITEUR ; sur une planche, la souris est
     celle de l'orateur, et la scène projetée ne doit pas bouger sous sa main. */
  const surMouvement = useCallback(
    (evenement: React.MouseEvent<HTMLDivElement>) => {
      if (reduit || !interactif) return;
      const rect = scene.current?.getBoundingClientRect();
      if (!rect) return;
      etat.current.parallaxe = {
        x: ((evenement.clientX - rect.left) / rect.width - 0.5) * 2,
        y: ((evenement.clientY - rect.top) / rect.height - 0.5) * 2,
      };
    },
    [reduit, interactif],
  );

  const compacte = mesures?.compacte ?? false;
  const noeudSurvole = interactif && survole !== null ? NOEUDS_DU_RESEAU[survole] : null;
  const carte = battement >= 0 ? BATTEMENTS[battement] : null;
  const noeudDeLaCarte = carte ? NOEUDS_DU_RESEAU.find((n) => n.id === carte.vers) : undefined;
  const tailleDuTerme = compacte ? 15 : Math.round(Math.min(24, Math.max(18, (mesures?.largeur ?? 780) * 0.028)));
  const positionDuCentre: CSSProperties = mesures ? { left: mesures.cx, top: mesures.cy } : { left: "50%", top: "45%" };
  const diametre = mesures?.diametreSphere ?? 200;
  const ouvrir = onOuvrir ?? SANS_GESTE;
  /* Survolé ou focalisé : la même intention, au pointeur comme au clavier. */
  const entrer = (i: number) => {
    setSurvole(i);
    void chargerLesFiches();
    onIntention?.();
  };

  return (
    <Scene
      ref={scene}
      $compacte={compacte}
      data-plonge={plonge !== null ? "true" : "false"}
      role={interactif ? "group" : "img"}
      aria-label={
        interactif
          ? `Les services de ${MARQUE.nom}`
          : `Les services de ${MARQUE.nom} : ${NOEUDS_DU_RESEAU.map((n) => n.libelle).join(", ")}`
      }
      onMouseMove={surMouvement}
      onMouseLeave={() => {
        etat.current.parallaxe = { x: 0, y: 0 };
        setSurvole(null);
      }}
    >
      <Couche data-couche="reseau" aria-hidden={interactif ? undefined : true}>
        <Halo $diametre={diametre} style={positionDuCentre} />

        <Traits aria-hidden="true" focusable="false">
          <defs>
            <linearGradient
              id="systeme-trait"
              gradientUnits="userSpaceOnUse"
              ref={(el) => {
                (registre.degrade as { current: SVGLinearGradientElement | null }).current = el;
              }}
            >
              <stop offset="0" stopColor={nuit.marque} stopOpacity="0" />
              <stop offset="0.7" stopColor={nuit.accent} stopOpacity="0.7" />
              <stop offset="1" stopColor={nuit.eclat} stopOpacity="1" />
            </linearGradient>
            <filter id="systeme-lueur" x="-200%" y="-200%" width="500%" height="500%">
              <feGaussianBlur stdDeviation="3.2" />
            </filter>
          </defs>
          {NOEUDS_DU_RESEAU.map((noeud, i) => (
            <line
              key={`filament-${noeud.id}`}
              ref={(el) => {
                registre.filaments[i] = el;
              }}
              stroke={nuit.accent}
              strokeWidth={1}
              strokeLinecap="round"
              style={{ opacity: 0 }}
            />
          ))}
          {LIENS_EN_INDEX.map(([a, b], k) => (
            <path
              key={`lien-${a}-${b}`}
              ref={(el) => {
                registre.liens[k] = el;
              }}
              fill="none"
              stroke={nuit.accent}
              strokeWidth={1.2}
              strokeDasharray="2 5"
              strokeLinecap="round"
              style={{ opacity: 0 }}
            />
          ))}
          <line
            ref={(el) => {
              (registre.fil as { current: SVGLineElement | null }).current = el;
            }}
            stroke={nuit.accent}
            strokeWidth={1}
            strokeDasharray="3 4"
            style={{ opacity: 0 }}
          />
          <path
            ref={(el) => {
              (registre.trainee as { current: SVGPathElement | null }).current = el;
            }}
            fill="none"
            stroke="url(#systeme-trait)"
            strokeWidth={2.4}
            strokeLinecap="round"
            style={{ opacity: 0 }}
          />
          <circle
            ref={(el) => {
              (registre.tete as { current: SVGCircleElement | null }).current = el;
            }}
            r={4}
            fill={nuit.eclat}
            filter="url(#systeme-lueur)"
            style={{ opacity: 0 }}
          />
        </Traits>

        <Centre $diametre={diametre} style={positionDuCentre}>
          <SphereDeConnexions
            diametre={diametre}
            couleur={nuit.accent}
            densite={echelle}
            ref={(poignee) => {
              (registre.sphere as { current: PoigneeDeLaSphere | null }).current = poignee;
            }}
          />
          <Terme
            ref={(el) => {
              (registre.terme as { current: HTMLButtonElement | null }).current = el;
            }}
            type="button"
            $taille={tailleDuTerme}
            onClick={interactif ? onVoirTout : undefined}
            tabIndex={interactif ? undefined : -1}
            aria-label={interactif ? `${MARQUE.nom} — voir toutes les fonctionnalités` : undefined}
          >
            {terme ?? MARQUE.nom}
          </Terme>
        </Centre>

        {NOEUDS_DU_RESEAU.map((noeud, i) => (
          <Planete
            key={noeud.id}
            ref={(el) => {
              registre.planetes[i] = el;
            }}
            type="button"
            $compacte={compacte}
            data-service={noeud.id}
            data-tiroir={noeud.tiroir ? "true" : "false"}
            tabIndex={interactif ? undefined : -1}
            aria-label={interactif ? `${noeud.libelle} — ouvrir` : undefined}
            onMouseEnter={interactif ? () => entrer(i) : undefined}
            onFocus={interactif ? () => entrer(i) : undefined}
            onBlur={interactif ? () => setSurvole((s) => (s === i ? null : s)) : undefined}
            onClick={interactif ? (evenement) => ouvrir(noeud.id, evenement.currentTarget) : undefined}
          >
            <Disque $compacte={compacte}>
              <Glyphe trace={noeud.glyphe} />
            </Disque>
            {!compacte && <Libelle>{noeud.libelle}</Libelle>}
          </Planete>
        ))}

        <Carte
          ref={(el) => {
            (registre.carte as { current: HTMLDivElement | null }).current = el;
          }}
          aria-hidden="true"
          key={battement}
          style={sansCarte ? { display: "none" } : undefined}
        >
          {carte && noeudDeLaCarte && (
            <>
              <Glyphe trace={noeudDeLaCarte.glyphe} />
              <CarteTexte>
                <CarteTitre>{carte.titre}</CarteTitre>
                <CarteDetail>{carte.detail}</CarteDetail>
              </CarteTexte>
            </>
          )}
        </Carte>

        {noeudSurvole && !compacte && (
          <Suspense fallback={null}>
            <FichesDuSurvol
              key={noeudSurvole.id}
              id={noeudSurvole.id}
              ref={(el) => {
                (registre.fiches as { current: HTMLUListElement | null }).current = el;
              }}
            />
          </Suspense>
        )}
      </Couche>

      {interactif && !reduit && plonge === null && (
        <BoutonPause
          type="button"
          aria-pressed={pause}
          onClick={() => setPauseLocale((p) => !p)}
        >
          <IconePause enPause={pause} />
          {pause ? "Reprendre l'animation" : "Arrêter l'animation"}
        </BoutonPause>
      )}
    </Scene>
  );
}
