import { Suspense, useCallback, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { useReducedMotion } from "framer-motion";
import { useNavigate } from "react-router";
import { styled } from "styled-components";

import type { IdServiceDeLaMarque } from "@/shared/config/services-de-la-marque";
import { num, px } from "@/shared/design-tokens/scale";
import { lazyWithRetry } from "@/shared/utils/lazy-with-retry";

import { ReseauDuCabinet } from "./ReseauDuCabinet";
import { LARGEUR_MIN_SYSTEME } from "./systeme.reseau";

/**
 * Le système du cabinet — le visuel du héros de la porte d'entrée avocat, et
 * depuis le 2026-10-14 celui de la planche d'accueil d'une présentation : LA
 * MÊME pièce, montée dans deux cadres (il vivait dans le dossier de la landing ;
 * une planche qui en aurait recopié l'animation l'aurait vue diverger au
 * premier réglage).
 *
 * Croquis validé `charte-visuelle-juris-connect/croquis/2026-09-25-le-systeme-du-cabinet.md`
 * (William, 2026-09-25 : « Génial ! applique tes reco », puis le centre en deux
 * remarques — ni l'orbe de l'assistant, ni le C du logo : un réseau autour du
 * terme Juris-Connect).
 *
 * LE CADRE « vitrine » — deux formes, choisies par la largeur de la zone et non
 * de l'écran (la règle du croquis V6, 640 px depuis le 2026-09-25) :
 *   · le système — le réseau en volume, qui tourne, et la plongée qui ouvre un
 *     service dans la même scène ;
 *   · la frise — au-dessous, le réseau vu de face, compact et sans libellé, puis
 *     les services en frise dépliable.
 *
 * LE CADRE « planche » — la scène de la vitrine, composée à sa largeur de
 * référence puis mise à l'échelle d'un bloc pour remplir son cadre : rien ne se
 * recompose, tout grandit ensemble, la sphère redessinée plus dense. Sans
 * plongée, sans fiche, sans bouton de pause : l'orateur la tient. `battement`
 * la pilote (un battement par clic) ; sans lui, ils s'enchaînent comme sur la
 * vitrine.
 */

/* La plongée se charge à l'INTENTION — dès qu'un service est survolé ou
   focalisé —, pas au clic : le morceau est là quand le clic arrive, et le
   panneau s'ouvre sans attente. `lazyWithRetry` et non `lazy` : un onglet
   resté ouvert pendant un déploiement demande un morceau qui a changé de nom,
   et la vitrine est la page qu'on laisse ouverte. */
const chargerLaPlongee = () => import("./PlongeeDuSysteme");
const PlongeeDuSysteme = lazyWithRetry(chargerLaPlongee);
const preparerLaPlongee = () => {
  void chargerLaPlongee();
};

/* La frise ne sert qu'aux zones étroites (sous LARGEUR_MIN_SYSTEME) : au
   bureau, elle ne se charge jamais — l'écran tirait trois fichiers de plus
   que son plafond (173 pour 170, mesuré le 2026-09-25). */
const FriseDuSysteme = lazyWithRetry(() =>
  import("./FriseDuSysteme").then((m) => ({ default: m.FriseDuSysteme })),
);

/** La largeur de référence d'une planche : celle où la vitrine plafonne (px(1100), 880 px rendus). */
const LARGEUR_DE_REFERENCE = num(1100);
/** La proportion de la scène complète (`reseau.styles.ts`, `Scene`). */
const PROPORTION = 1.18;

/* Au-delà de ~880 px, le système ne gagne rien à grandir (ses libellés ont une
   taille fixe) : en une colonne, il se centre au lieu de remplir la page. */
const Zone = styled.div`
  position: relative;
  width: 100%;
  max-width: ${px(1100)};
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: ${px(20)};
`;

const Enveloppe = styled.div`
  position: relative;
  width: 100%;
`;

/** Le cadre d'une planche : il prend toute la place qu'on lui donne. */
const CadreDePlanche = styled.div`
  position: relative;
  width: 100%;
  height: 100%;
  min-height: ${px(300)};
  overflow: hidden;
`;

/** La scène à sa largeur de référence, centrée, mise à l'échelle par le cadre. */
const SceneALEchelle = styled.div`
  position: absolute;
  left: 50%;
  top: 50%;
  width: ${px(1100)};
  transform-origin: center center;
`;

interface ProprietesDePlanche {
  cadre: "planche";
  /** Le battement à jouer, un par clic (−1 : aucun encore). Absent : ils s'enchaînent seuls. */
  battement?: number;
  /** Arrête tout ce qui bouge, à la demande de l'orateur. */
  enPause?: boolean;
  /** L'entrée dispersée : les services épars tant que `reliee` est faux (README). */
  dispersion?: { reliee: boolean };
  /** La vitesse du flux des battements (1 : celle de la landing). */
  cadence?: number;
  /** Le contenu du nom central — un nom qui se recompose, par exemple. */
  terme?: ReactNode;
  /** La carte du battement se tait : la planche dit le battement elle-même (un dossier qui reçoit ses tampons). */
  sansCarte?: boolean;
}

type Proprietes = { cadre?: "vitrine" } | ProprietesDePlanche;

export function SystemeDuCabinet(proprietes: Proprietes) {
  if (proprietes.cadre === "planche") {
    return <SystemeEnPlanche {...proprietes} />;
  }
  return <SystemeEnVitrine />;
}

function SystemeEnPlanche({ battement, enPause, dispersion, cadence, terme, sansCarte }: ProprietesDePlanche) {
  const mouvementReduit = useReducedMotion() === true;
  const cadre = useRef<HTMLDivElement>(null);
  /* Deux échelles : `locale`, celle que le cadre applique à la scène ; `ecran`,
     l'agrandissement TOTAL que la scène subit à l'écran — le réseau mesure sa
     scène à l'écran et la divise par elle. Elles ne diffèrent que si un ANCÊTRE
     est lui-même mis à l'échelle : la toile 16:9 d'un deck (Pitch Night,
     2026-10-14), où la mesure à l'écran du seul cadre comptait l'agrandissement
     deux fois. */
  const [echelle, setEchelle] = useState({ locale: 1, ecran: 1 });

  useLayoutEffect(() => {
    const el = cadre.current;
    if (!el) return;
    const mesurer = () => {
      const largeur = el.offsetWidth;
      const hauteur = el.offsetHeight;
      if (largeur <= 0 || hauteur <= 0) return;
      const locale = Math.min(largeur / LARGEUR_DE_REFERENCE, hauteur / (LARGEUR_DE_REFERENCE / PROPORTION));
      const ancetre = el.getBoundingClientRect().width / largeur || 1;
      setEchelle((e) =>
        Math.abs(e.locale - locale) < 1e-4 && Math.abs(e.ecran - locale * ancetre) < 1e-4
          ? e
          : { locale, ecran: locale * ancetre },
      );
    };
    mesurer();
    const observateur = new ResizeObserver(mesurer);
    observateur.observe(el);
    // L'agrandissement d'un ancêtre change sans changer la taille du cadre
    // (le plein écran du deck) : la fenêtre le dit, et la mesure attend que
    // l'ancêtre ait posé sa nouvelle échelle.
    let differee = 0;
    const auRedimensionnement = () => {
      window.clearTimeout(differee);
      differee = window.setTimeout(mesurer, 160);
    };
    window.addEventListener("resize", auRedimensionnement);
    return () => {
      observateur.disconnect();
      window.clearTimeout(differee);
      window.removeEventListener("resize", auRedimensionnement);
    };
  }, []);

  return (
    <CadreDePlanche ref={cadre}>
      <SceneALEchelle style={{ transform: `translate(-50%, -50%) scale(${echelle.locale})` }}>
        <ReseauDuCabinet
          reduit={mouvementReduit}
          plonge={null}
          interactif={false}
          echelle={echelle.ecran}
          battementPilote={battement ?? null}
          enPause={enPause}
          dispersion={dispersion ?? null}
          cadence={cadence}
          terme={terme}
          sansCarte={sansCarte}
        />
      </SceneALEchelle>
    </CadreDePlanche>
  );
}

function SystemeEnVitrine() {
  const navigate = useNavigate();
  const mouvementReduit = useReducedMotion() === true;
  const zone = useRef<HTMLDivElement>(null);
  const [largeur, setLargeur] = useState(0);
  const [plonge, setPlonge] = useState<IdServiceDeLaMarque | null>(null);
  const [ouvertDansLaFrise, setOuvertDansLaFrise] = useState<IdServiceDeLaMarque | null>(null);
  /** Le service qui a ouvert la plongée : il retrouve le focus à la fermeture. */
  const declencheur = useRef<HTMLElement | null>(null);

  useLayoutEffect(() => {
    const el = zone.current;
    if (!el) return;
    const mesurer = () => setLargeur(el.getBoundingClientRect().width);
    mesurer();
    const observateur = new ResizeObserver(mesurer);
    observateur.observe(el);
    return () => observateur.disconnect();
  }, []);

  const enFrise = largeur > 0 && largeur < LARGEUR_MIN_SYSTEME;

  const ouvrir = useCallback(
    (id: IdServiceDeLaMarque, depuis: HTMLElement) => {
      if (enFrise) {
        setOuvertDansLaFrise(id);
        requestAnimationFrame(() =>
          document.getElementById(`frise-${id}`)?.scrollIntoView({ behavior: mouvementReduit ? "auto" : "smooth", block: "center" }),
        );
        return;
      }
      declencheur.current = depuis;
      setPlonge(id);
    },
    [enFrise, mouvementReduit],
  );

  const fermer = useCallback(() => {
    setPlonge(null);
    requestAnimationFrame(() => declencheur.current?.focus());
  }, []);

  return (
    <Zone ref={zone}>
      <Enveloppe>
        <ReseauDuCabinet
          reduit={mouvementReduit}
          plonge={enFrise ? null : plonge}
          onOuvrir={ouvrir}
          onIntention={enFrise ? undefined : preparerLaPlongee}
          onVoirTout={() => navigate("/fonctionnalites")}
        />
        {!enFrise && plonge && (
          <Suspense fallback={null}>
            <PlongeeDuSysteme
              serviceId={plonge}
              mouvementReduit={mouvementReduit}
              onChanger={setPlonge}
              onFermer={fermer}
            />
          </Suspense>
        )}
      </Enveloppe>
      {enFrise && (
        <Suspense fallback={null}>
          <FriseDuSysteme
            ouvert={ouvertDansLaFrise}
            mouvementReduit={mouvementReduit}
            onBasculer={(id) => setOuvertDansLaFrise((o) => (o === id ? null : id))}
          />
        </Suspense>
      )}
    </Zone>
  );
}
