/**
 * Sentry Configuration
 *
 * Centralized Sentry configuration for error and performance monitoring.
 * Configure the DSN in environment variables.
 */

import * as Sentry from '@sentry/react';
import { useEffect } from 'react';
import { useLocation, useNavigationType, createRoutesFromChildren, matchRoutes } from 'react-router';
import { isLawyerApp as _isLawyerApp } from '@/app/app-context';
import { limiterRafale } from '@/shared/observability/sentry-burst-filter';
import { ecarterLaSaturationDUnRobot } from '@/shared/observability/saturation-provoquee-par-un-robot';

import { getRuntimeEnv } from '@/shared/utils/runtime-env';
import { lireLeDsnSentry } from '@/shared/config/sentry-dsn';
// Scrubbing PII : split règle 23 — voir sentry-scrub.ts
import { scrubPii, scrubTransactionEvent } from './sentry-scrub';

const SENTRY_DSN = lireLeDsnSentry();

// ── L'étage vient de la config RUNTIME, jamais de `MODE` (2026-08-04) ───────
//
// `import.meta.env.MODE` vaut « production » dès qu'on fait un build de
// production — c'est-à-dire sur les TROIS étages déployés. Les erreurs de dev
// et de beta arrivaient donc dans Sentry étiquetées `environment: production`,
// exactement comme côté back (`back/src/common/config/sentry.config.ts`).
//
// L'objectif du runtime-env est d'ailleurs UNE image front pour tous les
// étages : avec `MODE`, cette image ne pourrait par construction jamais dire
// où elle tourne. `VITE_SENTRY_ENVIRONMENT` est déjà posée par
// `docker/frontend/entrypoint.sh` — il ne manquait que la lecture.
//
// Le repli sur `MODE` reste : en local, en test, ou si `env.js` n'est pas
// encore servi, le comportement est inchangé (contrat de migration phase 1).
//
// ⚠ La valeur est NORMALISÉE, et ce n'est pas cosmétique. Les seuils plus bas
// comparent à `'production'` : une valeur `prod` — la forme que prend
// `ENVIRONMENT_NAME` côté back — les ferait tous basculer sur la branche
// « non-prod », soit un `tracesSampleRate` de 0,1 au lieu de 0,02. Ce fix
// aurait alors QUINTUPLÉ la consommation de quota en production, c'est-à-dire
// aggravé précisément ce qu'il corrige.
const STAGE_BRUT = (
  getRuntimeEnv('VITE_SENTRY_ENVIRONMENT') ||
  import.meta.env.MODE ||
  'development'
)
  .trim()
  .toLowerCase();
const ENVIRONMENT =
  STAGE_BRUT === 'prod'
    ? 'production'
    : STAGE_BRUT === 'dev'
      ? 'development'
      : STAGE_BRUT;
const APP_VERSION = import.meta.env.VITE_GIT_SHA || import.meta.env.VITE_APP_VERSION || '1.0.0';


/**
 * Hôtes vers lesquels le navigateur transmet l'en-tête `sentry-trace`.
 *
 * EXPORTÉE POUR ÊTRE TESTÉE, et c'est la raison d'être de cette constante :
 * la liste vivait à l'intérieur de `initSentry()`, donc hors d'atteinte de tout
 * banc. Elle y a porté pendant des mois un motif qui ne couvrait ni `avocat.`
 * ni `admin.` — l'espace où travaillent les avocats et celui de
 * l'administration — sans que rien ne puisse le dire.
 *
 * Ce réglage décide À QUI un en-tête est transmis : il se juge sur ses
 * ADJACENTS (`juris-power.com.attaquant.net`, `fauxjuris-power.com`), jamais
 * sur ses cas francs. Son banc :
 * `front/src/shared/config/__tests__/sentry-trace-propagation.test.ts`.
 */
export const TRACE_PROPAGATION_TARGETS: (string | RegExp)[] = [
  'localhost',
  /^https:\/\/juris-power\.dev\.local/,
  /^https:\/\/([a-z0-9-]+\.)*(juris-power\.com|juris-connect\.fr)(\/|$)/,
];

// Module-level flag — Sentry Session Replay cannot be re-initialized after close
let sentryEverInitialized = false;

/**
 * Initialize Sentry
 * Call this in main.tsx before rendering the app
 */
export function initSentry(): void {
  // Only initialize if DSN is configured
  if (!SENTRY_DSN) {
    if (import.meta.env.DEV) {
      // eslint-disable-next-line no-console
      console.info('[Sentry] DSN not configured - monitoring disabled');
    }
    return;
  }

  // Prevent double initialization — Session Replay does not support multiple instances.
  // getClient() returns undefined after Sentry.close(), but replay state persists.
  if (sentryEverInitialized || Sentry.getClient()) {
    return;
  }
  sentryEverInitialized = true;

  Sentry.init({
    dsn: SENTRY_DSN,
    environment: ENVIRONMENT,
    release: `juris-power@${APP_VERSION}`,

    // Tunnel proxy to bypass ad-blockers (Brave, uBlock Origin)
    // Désactivé en dev (le backend local n'a pas les credentials Sentry)
    ...(ENVIRONMENT !== 'development' && { tunnel: '/back/sentry-tunnel' }),

    // Performance Monitoring — RABAISSE le 2026-07-30 (arbitrage William :
    // rester sur le plan Sentry actuel). Le quota d'ORGANISATION s'est epuise le
    // 13 juillet — front et back se le partagent, donc l'un peut aveugler
    // l'autre. Les ERREURS ne sont PAS echantillonnees (aucun `sampleRate`) :
    // baisser les traces ne degrade pas la detection, seulement la finesse des
    // mesures de performance, qui s'obtient tres bien par sondage.
    //
    // HORS PRODUCTION : 1.0 → 0.1 le 2026-08-02.
    //
    // Le 100 % hors prod était l'angle mort de la baisse du 30 juillet, qui
    // n'avait touché que la production. Mesure du 2026-08-02, sur 24 h :
    // 74 967 spans rejetés faute de quota, contre 303 erreurs — les erreurs
    // pesaient 0,2 % du volume refusé. Et la production, à 2 %, n'y était pour
    // presque rien : c'est le développement, à 100 %, qui remplissait le quota
    // que la production ne pouvait plus utiliser. Même schéma que les
    // connexions PostgreSQL corrigées le même jour.
    //
    // 10 % suffit hors prod : une lenteur en local se reproduit à volonté, on
    // n'a pas besoin de l'enregistrer à chaque fois. Ce qui exigeait 100 %,
    // c'était l'idée qu'on ne peut pas rejouer — faux en développement.
    //
    // ⚠ Le MÊME réglage existe côté back (`back/src/common/config/sentry.config.ts`).
    // Les deux se partagent le quota d'organisation : n'en corriger qu'un ne
    // corrige que la moitié.
    tracesSampleRate: ENVIRONMENT === 'production' ? 0.02 : 0.1,

    // Session Replay — disabled (no cookies = no consent banner needed)
    replaysSessionSampleRate: 0,
    replaysOnErrorSampleRate: 0,

    // AUCUN PROFIL — décision de William du 2026-09-23 : « si c'est payant, je ne
    // préfère pas le prévoir ». Le forfait Sentry n'en réserve aucun : chacun se
    // paierait sur l'enveloppe à la demande commune aux erreurs. Retiré avec
    // `browserProfilingIntegration` (inerte jusque-là : 0 profil reçu sur la période).

    // Distributed Tracing — propagation des headers sentry-trace/baggage
    //
    // ⚠️ CORRIGÉ LE 2026-09-11 — le motif précédent ne couvrait PAS l'espace
    // avocat. Il valait `/^https:\/\/(dev\.|beta\.)?juris-power\.com/`, donc
    // l'apex nu, `dev.` et `beta.` — et RIEN d'autre. Mesuré :
    //   ✓ juris-power.com · dev. · beta.
    //   ✗ avocat.juris-power.com   ← l'espace où travaillent les avocats
    //   ✗ admin.juris-power.com
    //   ✗ www.juris-power.com      ← l'apex canonique
    //   ✗ avocat.dev.juris-power.com
    // Sur ces hôtes, l'en-tête `sentry-trace` n'était pas émis : une erreur
    // front et l'erreur back qu'elle déclenche restaient DEUX événements sans
    // lien. Le défaut existait avant toute migration de marque.
    //
    // Le nouveau motif accepte tout sous-domaine des DEUX marques, et rien
    // d'autre. Ce réglage décide À QUI le navigateur transmet un en-tête de
    // trace : il se juge sur ses ADJACENTS, pas sur ses cas francs. Éprouvé sur
    // 14 cas, tous refusés — notre domaine en PRÉFIXE de celui d'un tiers
    // (`juris-power.com.attaquant.net`), un nom qui COMMENCE par le nôtre
    // (`fauxjuris-power.com`), nos deux marques sur un mauvais TLD, et la
    // variante en `http://`. Le banc les nomme un par un.
    //
    // `juris-connect.fr` y figure AVANT la bascule : la propagation doit
    // fonctionner dès la première seconde où le domaine sert, sans redéploiement
    // du front. Tant qu'il ne sert rien, la ligne est inerte.
    //
    // La liste vit dans `TRACE_PROPAGATION_TARGETS`, en haut de ce fichier —
    // définie DEHORS pour qu'un banc puisse l'atteindre.
    tracePropagationTargets: TRACE_PROPAGATION_TARGETS,

    // Filter out non-critical errors and scrub PII
    beforeSend(event, hint) {
      const error = hint.originalException;

      if (error instanceof Error) {
        const message = error.message.toLowerCase();

        // Drop network errors entirely — these are client-side (ad blocker, offline, API restart)
        if (
          message.includes('failed to fetch') ||
          message.includes('load failed') ||
          message.includes('networkerror when attempting to fetch') ||
          message.includes('the request failed and the interceptors did not return')
        ) {
          return null;
        }

        // Drop 503 on API Rust — transitoire pendant les redémarrages
        if (/\[api-rust\] error 503/i.test(message)) {
          return null;
        }

        // Une saturation qu'un ROBOT s'inflige à lui-même n'apprend rien.
        // Mesure du 2026-08-22, 30 jours de production : 2 451 erreurs 429
        // émises par HeadlessChrome contre 48 par de vrais navigateurs — 98 %
        // de bruit, qui noyait le signal ET consommait le quota de
        // l'ORGANISATION (cf. INCIDENT_SENTRY_QUOTA_EXHAUSTED).
        // Tout le reste de ce qu'un robot détecte PASSE : nos bancs e2e sont
        // une source de détection payée. Détail et périmètre exact :
        // `saturation-provoquee-par-un-robot.ts`.
        if (ecarterLaSaturationDUnRobot(event, error.message) === null) {
          return null;
        }
      }

      // Drop FetchError class from generated API client
      if (error && typeof error === 'object' && 'name' in error && (error as { name: string }).name === 'FetchError') {
        return null;
      }

      // Filet contre les rafales (2026-07-30). Le quota Sentry est celui de
      // l'ORGANISATION : il est partagé avec le back, et protéger un seul côté
      // laisse l'autre libre de l'épuiser pour tout le monde. Une boucle de
      // rendu qui lève se multiplie ici par le nombre d'onglets ouverts.
      // Doctrine : documentation/agent-rules/sentry-burst-limiting.md
      const rafale = limiterRafale(event);
      if (rafale === null) {
        return null;
      }

      return scrubPii(rafale);
    },

    beforeSendTransaction(event) {
      return scrubTransactionEvent(event);
    },

    // Ignore errors from third-party scripts and browser extensions
    denyUrls: [
      /extensions\//i,
      /^chrome-extension:\/\//i,
      /^moz-extension:\/\//i,
      /js\.stripe\.com/i,
      /cdn\.jsdelivr\.net/i,
      /googleapis\.com/i,
    ],

    // Ignore specific errors
    ignoreErrors: [
      // Browser extensions
      /extensions\//i,
      /^chrome-extension:\/\//i,
      // Resize observer (benign — fires when layout shifts, not a real error)
      'ResizeObserver loop',
      /ResizeObserver loop completed with undelivered notifications/,
      // User cancelled
      'AbortError',
      // Non-error rejections (e.g. string thrown as error)
      'Non-Error promise rejection captured',
      'Non-Error exception captured',
      // Chunk loading failures after deployments (stale cache)
      /Loading chunk .* failed/,
      'ChunkLoadError',
      /Unable to preload CSS/,
      /Failed to fetch dynamically imported module/,
      /error loading dynamically imported module/,
      // API errors handled by the app (not bugs)
      /\[API-Rust\] Error 401/,
      /\[API-Rust\] (Error|Transient) (502|503|504)/,
      // /api/plans 500 — non-bloquant (degradation gracieuse home/onboarding)
      /\[API-Rust\] (Error|Non-critical) 500 on \/api\/(plans|lawyer\/[^\s?]+\/plans)/,
      // Network errors (ad blockers, offline, API restart)
      'Failed to fetch',
      'Load failed',
      'NetworkError when attempting to fetch resource',
      'The request failed and the interceptors did not return an alternative response',
      /ERR_BLOCKED_BY_CLIENT/,
      /net::ERR_/,
      // ServiceWorker (browser policy, offline, stale cache)
      /Registration failed/,
      /Failed to update a ServiceWorker/,
      /An unknown error occurred when fetching the script/,
      // WebSocket errors (transitoire — reconnect automatique)
      'websocket error',
      /WebSocket is closed/,
      // Generic rejections without useful info
      /^Rejected$/,
      'Rejected',
      // JSON.parse failures sur response API vide/HTML (502/504 nginx, body vide).
      // Ces erreurs sont systematiquement handled par les hooks (catch + fallback),
      // mais Sentry les capture quand meme. Cause #1 = API restart pendant deploy.
      // Source : JURIS-POWER-FRONT-4N (Firefox Mobile, /app/agenda).
      /JSON\.parse: unexpected character/i,
      /Unexpected token .* in JSON/i,
      /Unexpected end of JSON input/i,
      // React unmount race conditions (setState on unmounted component)
      /Can't perform a React state update on an unmounted component/,
      // Permissions API (some browsers don't support it)
      /permissions.*denied/i,
    ],

    // Integrations
    integrations: [
      // React Router v7 browser tracing for proper route grouping
      Sentry.reactRouterV7BrowserTracingIntegration({
        useEffect,
        useLocation,
        useNavigationType,
        createRoutesFromChildren,
        matchRoutes,
      }),

      // User Feedback Widget — formulaire de signalement post-crash
      // Uniquement sur les espaces connectés (avocat/admin), pas sur la vitrine client
      // autoInject: false on mobile to avoid overlapping with bottom nav bar and FAB
      Sentry.feedbackIntegration({
        autoInject: false,
        showBranding: false,
        colorScheme: 'system',
        triggerLabel: 'Signaler un problème',
        formTitle: 'Signaler un problème',
        submitButtonLabel: 'Envoyer',
        cancelButtonLabel: 'Annuler',
        nameLabel: 'Nom',
        namePlaceholder: 'Votre nom',
        emailLabel: 'Email',
        emailPlaceholder: 'votre@email.com',
        messageLabel: 'Description',
        messagePlaceholder: 'Décrivez le problème rencontré...',
        successMessageText: 'Merci pour votre retour !',
        enableScreenshot: true,
      }),
    ],
  });

  // ───────────────────────────────────────────────────────────────────────────
  // Tag came_from_email — trace les erreurs déclenchées par un clic sur un
  // lien dans un email (Brevo ajoute systématiquement utm_source=sendinblue
  // sur les liens trackés). Permet de configurer une alerte Sentry
  // "is:unresolved tag:came_from_email:true http.status_code:404" qui réagit
  // immédiatement si un template Brevo envoie un lien cassé en masse.
  //
  // Anti-incident 2026-04-28 (template 150 → 23 avocats prod sur lien 404).
  // Voir documentation/runbooks/EMAIL_LINK_INCIDENT.md
  // ───────────────────────────────────────────────────────────────────────────
  if (typeof window !== 'undefined' && window.location?.search) {
    const params = new URLSearchParams(window.location.search);
    const utmSource = params.get('utm_source');
    if (utmSource === 'sendinblue' || utmSource === 'brevo') {
      Sentry.setTag('came_from_email', 'true');
      const campaign = params.get('utm_campaign');
      if (campaign) Sentry.setTag('email_campaign', campaign.slice(0, 100));
    }
  }
}

/**
 * Set user context for better error tracking
 */
export function setSentryUser(user: { id: string; role?: string }): void {
  // Never send email to Sentry — PII scrubbing only covers beforeSend, not performance traces
  Sentry.setUser({
    id: user.id,
    role: user.role,
  });
}

/**
 * Clear user context on logout
 */
export function clearSentryUser(): void {
  Sentry.setUser(null);
}

/**
 * Add breadcrumb for navigation/action tracking
 */
export function addSentryBreadcrumb(
  category: string,
  message: string,
  data?: Record<string, unknown>,
  level: Sentry.SeverityLevel = 'info'
): void {
  Sentry.addBreadcrumb({
    category,
    message,
    data,
    level,
  });
}

/**
 * Capture an exception with context
 */
export function captureException(
  error: Error,
  context?: {
    tags?: Record<string, string>;
    extra?: Record<string, unknown>;
    level?: Sentry.SeverityLevel;
  }
): string {
  return Sentry.captureException(error, {
    tags: context?.tags,
    extra: context?.extra,
    level: context?.level,
  });
}

/**
 * Capture a message
 */
function _captureMessage(
  message: string,
  level: Sentry.SeverityLevel = 'info'
): string {
  return Sentry.captureMessage(message, level);
}

/**
 * Start a transaction for performance monitoring
 */
function _startTransaction(name: string, op: string): Sentry.Span | undefined {
  return Sentry.startInactiveSpan({ name, op });
}

/**
 * Check if Sentry is initialized
 */
export function isSentryEnabled(): boolean {
  const client = Sentry.getClient();
  return !!SENTRY_DSN && client !== undefined && client.getOptions().enabled !== false;
}

