/**
 * Persistance de position (fiabilité jour J, audit 2026-07-05).
 *
 * Problème couvert : l'écran projeté SEUL (sans pupitre ouvert), ou une
 * fenêtre unique, qui crashe / est rechargé (F5 réflexe, Chrome qui redémarre)
 * en pleine séance retombait à la scène 1 + écran d'accueil devant la salle —
 * le protocole hello ne restaure la position que si un pair a SURVÉCU.
 *
 * Scope volontaire = `sessionStorage` (une séance = un onglet) : survit au
 * reload, s'efface à la fermeture de l'onglet — pas de reprise fantôme d'une
 * séance d'hier. Clé par `channelId` (une clé par présentation) ; chaque
 * fenêtre a son sessionStorage isolé, donc audience et pupitre persistent
 * indépendamment puis se resynchronisent par hello. Moteur Storage canonique
 * (règle 85) : garde mode privé/quota, ne throw jamais.
 */
import { useEffect } from "react";

import { getSessionItem, setSessionItem } from "@/shared/utils/storage";

import type { PresentationSyncState } from "./presentation-definition";

const KEY_PREFIX = "presentation-position:";

export interface PersistedPosition {
  index: number;
  step: number;
  startedAt: number | null;
  /** true si une séance démarrée a été restaurée → sauter l'écran d'accueil. */
  restored: boolean;
}

type StoredPosition = Pick<
  PresentationSyncState,
  "index" | "step" | "startedAt"
>;

const EMPTY: StoredPosition = { index: 0, step: 0, startedAt: null };

export function readPersistedPosition(channelId: string): PersistedPosition {
  const raw = getSessionItem<StoredPosition>(`${KEY_PREFIX}${channelId}`, EMPTY);
  const index = Number.isFinite(raw.index) ? raw.index : 0;
  const step = Number.isFinite(raw.step) ? raw.step : 0;
  const startedAt =
    typeof raw.startedAt === "number" ? raw.startedAt : null;
  return { index, step, startedAt, restored: index > 0 || startedAt !== null };
}

export function usePersistPosition(
  channelId: string,
  state: StoredPosition,
): void {
  useEffect(() => {
    setSessionItem<StoredPosition>(`${KEY_PREFIX}${channelId}`, {
      index: state.index,
      step: state.step,
      startedAt: state.startedAt,
    });
  }, [channelId, state.index, state.step, state.startedAt]);
}
