import { useCallback, useEffect, useRef, type RefObject } from "react";

import { approcher, borner, douxEntreeSortie, ressort } from "@/shared/animations/scene/courbes";
import {
  cheminDuLien,
  controleDuLien,
  libellesMasques,
  opaciteSelonProfondeur,
  pointsDeLaTrainee,
  projeterSurOrbite,
  raccourcir,
  type Point2,
  type Projection,
} from "@/shared/animations/scene/geometrie";
import { poser, useHorlogeDeScene } from "@/shared/animations/scene/horloge";

import type { EtatDuReseau, RegistreDuReseau, TaillesLues } from "./reseau.types";
import { BATTEMENTS, RYTHME_DU_FLUX } from "./systeme.flux";
import {
  centreALEcran,
  compositionDeDepart,
  INDEX_DU_NOEUD,
  LIENS_EN_INDEX,
  NOEUDS_DU_RESEAU,
  placeEntreDispersionEtOrbite,
  placesDeLaDispersion,
  servicesALEcran,
  type MesuresDeLaScene,
} from "./systeme.reseau";

/**
 * L'animation du réseau du cabinet — ce que l'horloge écrit à chaque image.
 * L'horloge, la géométrie et les courbes sont celles du moteur d'animation
 * (`shared/animations/scene/`) ; ce fichier ne garde que la chorégraphie du
 * système.
 *
 * Rien ne passe par l'état React, sauf le changement de battement (toutes les
 * quatre secondes, pour le TEXTE de la carte) : les positions, les opacités,
 * les filaments, les liens et le trait sont écrits dans le DOM directement.
 *
 * LES TEMPS SONT DES DÉCISIONS, et ils se relisent ici :
 *   · un tour de la consultation en cent secondes, le cabinet en sens
 *     contraire à 70 % de cette vitesse — assez lent pour lire un libellé qui
 *     passe. Les deux orbites ne tournent PAS d'un bloc : cinq services d'un
 *     côté, sept de l'autre, il y en a toujours deux presque alignés, et un
 *     alignement figé se chevaucherait pour toujours ; en sens contraires, il
 *     ne fait que passer ;
 *   · un battement toutes les 3,8 s : le trait voyage 1,3 s, la carte vit
 *     2,5 s après l'arrivée — le battement suivant part quand elle s'efface,
 *     jamais deux cartes. La carte a sa PLACE, en haut à gauche de la scène,
 *     reliée au service d'arrivée par un fil : posée à côté du service, elle
 *     recouvrait les voisins (vu au navigateur le 2026-09-25) ;
 *   · l'entrée tient en 2,2 s, puis le premier trait part.
 *
 * Sur une planche de présentation, la scène se PILOTE (un battement au clic)
 * et peut ENTRER DISPERSÉE (les services épars rejoignent leur orbite au clic) :
 * le README du dossier dit comment, et pourquoi.
 */

const TOUR_MS = 100_000;
const TOUR_SPHERE_MS = 46_000;
const { periodeMs: PERIODE_MS, traitMs: TRAIT_MS, carteMs: CARTE_MS } = RYTHME_DU_FLUX;
const INTRO_MS = 2_200;
/** Le ralenti du survol : un cinquième de la vitesse (croquis, « Le survol »). */
const VITESSE_AU_SURVOL = 0.2;
/** Le cabinet tourne en sens contraire de la consultation, un peu moins vite. */
const SENS_DU_CABINET = -0.7;
/** La place de la carte dans la scène. */
const MARGE_DE_LA_CARTE = 10;

/**
 * Lit les tailles une fois par changement de mesures (et au chargement des
 * polices) — jamais à chaque image : lire une taille après avoir écrit des
 * positions force le navigateur à recalculer toute la mise en page.
 */
function lireLesTailles(registre: RegistreDuReseau, me: MesuresDeLaScene): TaillesLues | null {
  if (me.compacte) return null;
  const libelles = registre.planetes.map((planete) => {
    const libelle = planete?.lastElementChild;
    if (!planete || !(libelle instanceof HTMLElement) || libelle === planete.firstElementChild) return null;
    return {
      dx: libelle.offsetLeft - planete.offsetWidth / 2,
      dy: libelle.offsetTop - me.rayonDisque,
      l: libelle.offsetWidth,
      h: libelle.offsetHeight,
    };
  });
  const terme = registre.terme.current;
  let tailleDuTerme = { l: 0, h: 0 };
  if (terme) {
    const style = getComputedStyle(terme);
    const horizontal = (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
    const vertical = (parseFloat(style.paddingTop) || 0) + (parseFloat(style.paddingBottom) || 0);
    tailleDuTerme = {
      l: Math.max(0, terme.offsetWidth - horizontal),
      h: Math.max(0, terme.offsetHeight - vertical),
    };
  }
  return { libelles, terme: tailleDuTerme };
}

export function useAnimationDuReseau({
  registre,
  etat,
  mesures,
  reduit,
  onBattement,
}: {
  registre: RegistreDuReseau;
  etat: RefObject<EtatDuReseau>;
  mesures: RefObject<MesuresDeLaScene | null>;
  reduit: boolean;
  onBattement: (index: number) => void;
}) {
  const moteur = useRef({
    angle: 0,
    vitesse: 1,
    intro: reduit ? INTRO_MS : 0,
    flux: 0,
    battement: -1,
    /** Le dernier battement demandé, quand la scène est pilotée. */
    demande: -1,
    lacet: 0,
    pouls: 0,
    lacetSouris: 0,
    inclinaisonSouris: 0,
    arrivee: -1,
    arriveeDepuis: 0,
    tailles: null as TaillesLues | null,
    mesuresLues: null as MesuresDeLaScene | null,
    /** De combien chaque orbite tourne avant le premier geste (`compositionDeDepart`). */
    phases: { consultation: 0, cabinet: 0 },
    /** L'horloge de la dérive des services épars (entrée dispersée d'une planche). */
    derive: 0,
    places: [] as Point2[],
  });

  /* Les libellés se mesurent dans leur police : une fois celle-ci chargée, on
     relit (le premier rendu a pu se mesurer dans la police de secours). */
  useEffect(() => {
    let vivant = true;
    void document.fonts?.ready.then(() => {
      if (vivant) moteur.current.mesuresLues = null;
    });
    return () => {
      vivant = false;
    };
  }, []);
  const rappelBattement = useRef(onBattement);
  rappelBattement.current = onBattement;

  const image = useCallback(
    (dt: number) => {
      const s = moteur.current;
      const me = mesures.current;
      const e = etat.current;
      if (!me || !e) return;
      if (reduit) s.intro = e.dispersion !== null && !e.dispersion.reliee ? 0 : INTRO_MS;
      if (s.mesuresLues !== me) {
        s.tailles = lireLesTailles(registre, me);
        s.mesuresLues = me;
        // La composition de départ se choisit tant que rien n'a tourné — au
        // mouvement réduit, à chaque taille : c'est la seule qu'on verra.
        if (s.tailles && (reduit || s.angle === 0)) s.phases = compositionDeDepart(me, s.tailles);
        s.places = placesDeLaDispersion(me);
      }
      // Une planche à l'entrée dispersée retient l'intro tant que ses services ne sont pas reliés.
      const epars = e.dispersion !== null && !e.dispersion.reliee;

      // ── La vitesse, le temps, la souris ──
      const cible = e.pause || e.plonge ? 0 : e.survole !== null ? VITESSE_AU_SURVOL : 1;
      s.vitesse = approcher(s.vitesse, cible, dt, 350);
      if (!reduit) {
        s.angle += ((2 * Math.PI) / TOUR_MS) * s.vitesse * dt;
        s.lacet += ((2 * Math.PI) / TOUR_SPHERE_MS) * (e.pause || e.plonge ? 0 : 1) * dt;
        s.intro = epars ? 0 : Math.min(INTRO_MS, s.intro + dt);
        s.derive += dt;
      }
      s.lacetSouris = approcher(s.lacetSouris, me.compacte ? 0 : e.parallaxe.x * 0.12, dt, 400);
      s.inclinaisonSouris = approcher(s.inclinaisonSouris, me.compacte ? 0 : e.parallaxe.y * 0.05, dt, 400);

      const scene = {
        cx: me.cx,
        cy: me.cy,
        aplatissement: me.aplatissement + s.inclinaisonSouris,
        focale: me.focale,
      };
      const centre: Point2 = { x: me.cx, y: me.cy };
      const apparitionSphere = borner(s.intro / 1000);

      // ── Le flux : quel battement, où en est son trait ──
      const pilote = e.battementPilote !== null;
      if (pilote && e.battementPilote !== s.demande) {
        // Un battement demandé repart du début de SA période : le trait, puis la carte.
        s.demande = e.battementPilote ?? -1;
        s.flux = s.demande >= 0 ? (s.demande % BATTEMENTS.length) * PERIODE_MS : 0;
        s.battement = -1;
      }
      const fluxOuvert = !reduit && s.intro >= INTRO_MS && (!pilote || s.demande >= 0);
      const phaseAvant = s.flux % PERIODE_MS;
      const fluxLibre = !e.pause && !e.plonge && e.survole === null;
      // Un trait en route finit sa course, même si l'on survole : un trait
      // figé au milieu d'un lien se lit comme une panne.
      if (fluxOuvert && (fluxLibre || phaseAvant < TRAIT_MS)) s.flux += dt * e.cadence;
      // Piloté, le battement s'arrête au bout de sa carte, sans entamer le
      // suivant : il attend la prochaine demande.
      if (pilote && s.demande >= 0) {
        s.flux = Math.min(s.flux, (s.demande % BATTEMENTS.length) * PERIODE_MS + PERIODE_MS - 1);
      }
      const index = Math.floor(s.flux / PERIODE_MS) % BATTEMENTS.length;
      const phase = s.flux % PERIODE_MS;
      if (fluxOuvert && index !== s.battement) {
        s.battement = index;
        rappelBattement.current(index);
      }
      // Piloté, au bout de sa carte, le battement s'est tu : plus de trait, plus
      // de carte, plus de service allumé — la scène attend le clic suivant.
      const enAttente = pilote && phase >= PERIODE_MS - 1;
      const battement = fluxOuvert && !enAttente ? BATTEMENTS[index] : null;
      const de = battement ? (INDEX_DU_NOEUD.get(battement.de) ?? -1) : -1;
      const vers = battement ? (INDEX_DU_NOEUD.get(battement.vers) ?? -1) : -1;
      const carteVisible = battement !== null && phase >= TRAIT_MS && phase < TRAIT_MS + CARTE_MS;
      if (battement && phaseAvant < TRAIT_MS && phase >= TRAIT_MS) {
        s.pouls = 1;
        s.arrivee = vers;
        s.arriveeDepuis = 0;
      }
      s.pouls = Math.max(0, s.pouls - dt / 700);
      s.arriveeDepuis += dt;

      // ── Les services ──
      const rayons: number[] = [];
      const projections: Projection[] = NOEUDS_DU_RESEAU.map((noeud, i) => {
        const arrivee = borner((s.intro - 450 - i * 60) / 800);
        const consultation = noeud.orbite === "consultation";
        const disperse = e.dispersion !== null && s.places.length > i;
        const k = reduit ? arrivee : ressort(arrivee);
        const rayon = (consultation ? me.rayonConsultation : me.rayonCabinet) * (reduit || disperse ? 1 : k);
        rayons.push(rayon);
        const sens = consultation ? 1 : SENS_DU_CABINET;
        const phase = consultation ? s.phases.consultation : s.phases.cabinet;
        const orbite = projeterSurOrbite(noeud.angle + phase + s.angle * sens + s.lacetSouris, rayon, scene);
        const p = disperse ? placeEntreDispersionEtOrbite(s.places[i], orbite, k, s.derive, i) : orbite;
        // La profondeur RÉELLE : deux orbites de rayons différents se comparent
        // en pixels, pas en fraction de leur rayon.
        const z = p.profondeur * rayon;
        const el = registre.planetes[i];
        if (el) {
          el.style.transform = `translate3d(${p.x.toFixed(1)}px, ${p.y.toFixed(1)}px, 0) translate(-50%, -${me.rayonDisque}px)`;
          el.style.setProperty("--e", p.echelle.toFixed(3));
          el.style.setProperty("--o", opaciteSelonProfondeur(p.profondeur).toFixed(3));
          el.style.opacity = (disperse ? 0.5 + 0.5 * borner(arrivee * 1.6) : borner(arrivee * 1.6)).toFixed(3);
          // Épars, un service est éteint ; il reprend sa couleur en s'accrochant.
          if (disperse) el.style.filter = arrivee >= 1 ? "" : `grayscale(${(1 - arrivee).toFixed(2)}) brightness(${(0.7 + 0.3 * arrivee).toFixed(2)})`;
          // Devant le centre (z-index 25) ce qui vient vers le visiteur,
          // derrière lui le reste ; le service survolé passe devant tout.
          const relatif = z / me.rayonCabinet;
          el.style.zIndex = String(
            e.survole === i ? 44 : z > 0 ? 30 + Math.round(relatif * 9) : 10 + Math.round((relatif + 1) * 7),
          );
          const actif = e.survole === i || (carteVisible && i === vers) || (battement !== null && phase < TRAIT_MS && (i === de || i === vers));
          poser(el, "data-actif", actif ? "true" : "false");
          poser(el, "data-arrive", s.arrivee === i && s.arriveeDepuis < 900 ? "true" : "false");
        }
        return p;
      });

      // ── L'occlusion des libellés : ce qui est recouvert par plus proche se tait ──
      const tailles = s.tailles;
      if (tailles) {
        const masques = libellesMasques(
          servicesALEcran(projections, rayons, tailles, me),
          centreALEcran(me, tailles),
          e.survole,
        );
        masques.forEach((masque, i) => {
          const accroche = !epars && borner((s.intro - 450 - i * 60) / 800) > 0.6;
          registre.planetes[i]?.style.setProperty("--l", masque || (e.dispersion !== null && !accroche) ? "0" : "1");
        });
      }

      // ── Les filaments : du bord de la sphère au bord de chaque disque ──
      const rayonSphere = (me.diametreSphere / 2) * 0.9;
      projections.forEach((p, i) => {
        const ligne = registre.filaments[i];
        if (!ligne) return;
        const dx = p.x - centre.x;
        const dy = p.y - centre.y;
        const n = Math.hypot(dx, dy) || 1;
        const depart = { x: centre.x + (dx / n) * rayonSphere, y: centre.y + (dy / n) * rayonSphere };
        const fin = raccourcir(depart, p, me.rayonDisque * p.echelle + 4);
        const eteint = n < rayonSphere + me.rayonDisque;
        poser(ligne, "x1", depart.x.toFixed(1));
        poser(ligne, "y1", depart.y.toFixed(1));
        poser(ligne, "x2", fin.x.toFixed(1));
        poser(ligne, "y2", fin.y.toFixed(1));
        const allume = e.survole === i || i === de || i === vers;
        const base = 0.14 + 0.2 * ((p.profondeur + 1) / 2);
        const arrivee = borner((s.intro - 450 - i * 60) / 800);
        ligne.style.opacity = eteint ? "0" : ((allume ? 0.7 : base) * arrivee).toFixed(3);
      });

      // ── Les liens entre services : des courbes qui s'écartent du centre ──
      const degagement = (me.diametreSphere / 2) * 1.12;
      const bord = (a: Projection, b: Projection) => raccourcir(b, a, me.rayonDisque * a.echelle + 3);
      LIENS_EN_INDEX.forEach(([ia, ib], k) => {
        const chemin = registre.liens[k];
        if (!chemin) return;
        const a = projections[ia];
        const b = projections[ib];
        const q = controleDuLien(a, b, centre, degagement);
        poser(chemin, "d", cheminDuLien(bord(a, b), q, bord(b, a)));
        const enRoute = (ia === de && ib === vers) || (ia === vers && ib === de);
        const touche = e.survole === ia || e.survole === ib;
        const apparition = borner((s.intro - 1400) / 600);
        chemin.style.opacity = ((enRoute ? 0.55 : touche ? 0.4 : 0.13) * apparition).toFixed(3);
      });

      // ── Le trait de lumière ──
      const trainee = registre.trainee.current;
      const tete = registre.tete.current;
      const degrade = registre.degrade.current;
      if (trainee && tete && degrade) {
        if (battement && de >= 0 && vers >= 0 && phase < TRAIT_MS) {
          const a = projections[de];
          const b = projections[vers];
          const q = controleDuLien(a, b, centre, degagement);
          const t = borner(phase / TRAIT_MS);
          const points = pointsDeLaTrainee(bord(a, b), q, bord(b, a), douxEntreeSortie(t));
          const [avant] = points;
          const queue = points[points.length - 1];
          poser(trainee, "d", `M${points.map((p) => `${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join("L")}`);
          poser(degrade, "x1", queue.x.toFixed(1));
          poser(degrade, "y1", queue.y.toFixed(1));
          poser(degrade, "x2", avant.x.toFixed(1));
          poser(degrade, "y2", avant.y.toFixed(1));
          poser(tete, "cx", avant.x.toFixed(1));
          poser(tete, "cy", avant.y.toFixed(1));
          const fondu = borner(Math.min(t / 0.08, (1 - t) / 0.06));
          trainee.style.opacity = fondu.toFixed(3);
          tete.style.opacity = fondu.toFixed(3);
        } else {
          trainee.style.opacity = "0";
          tete.style.opacity = "0";
        }
      }

      // ── La carte du battement : à sa place, reliée par un fil au service ──
      const carte = registre.carte.current;
      const fil = registre.fil.current;
      if (carte) {
        // Au téléphone, la scène est trop petite pour une carte : le trait
        // suffit, et la frise en dessous dit le reste. Pendant la plongée, elle
        // se taisait mal — on la voyait à travers le rail.
        if (carteVisible && vers >= 0 && !me.compacte && !e.plonge) {
          const p = projections[vers];
          const largeur = carte.offsetWidth || 232;
          const hauteur = carte.offsetHeight || 64;
          const age = phase - TRAIT_MS;
          const fondu = borner(Math.min(age / 180, (CARTE_MS - age) / 320));
          carte.style.transform = `translate3d(${MARGE_DE_LA_CARTE}px, ${MARGE_DE_LA_CARTE}px, 0)`;
          carte.style.opacity = fondu.toFixed(3);
          poser(carte, "data-visible", "true");
          if (fil) {
            const depart = { x: MARGE_DE_LA_CARTE + largeur, y: MARGE_DE_LA_CARTE + hauteur / 2 };
            const bout = raccourcir(depart, p, me.rayonDisque * p.echelle + 6);
            poser(fil, "x1", depart.x.toFixed(1));
            poser(fil, "y1", depart.y.toFixed(1));
            poser(fil, "x2", bout.x.toFixed(1));
            poser(fil, "y2", bout.y.toFixed(1));
            fil.style.opacity = (fondu * 0.55).toFixed(3);
          }
        } else {
          carte.style.opacity = "0";
          poser(carte, "data-visible", "false");
          if (fil) fil.style.opacity = "0";
        }
      }

      // ── Les fiches du service survolé ──
      const fiches = registre.fiches.current;
      if (fiches && e.survole !== null && !me.compacte) {
        const p = projections[e.survole];
        const aDroite = p.x >= centre.x;
        const largeur = fiches.offsetWidth || 180;
        const hauteur = fiches.offsetHeight || 80;
        const ecart = me.rayonDisque * p.echelle + 18;
        const x = borner(aDroite ? p.x + ecart : p.x - ecart - largeur, 4, me.largeur - largeur - 4);
        const y = borner(p.y - hauteur / 2, 4, me.hauteur - hauteur - 4);
        fiches.style.transform = `translate3d(${x.toFixed(1)}px, ${y.toFixed(1)}px, 0)`;
        poser(fiches, "data-cote", aDroite ? "droite" : "gauche");
      }

      registre.sphere.current?.dessiner(s.lacet, apparitionSphere, s.pouls);
    },
    [registre, etat, mesures, reduit],
  );

  useHorlogeDeScene(image, { actif: !reduit, cible: registre.scene });

  /** Une image, hors horloge : au mouvement réduit, et quand la scène change de taille. */
  const redessiner = useCallback(() => image(0), [image]);

  return { redessiner };
}
