/**
 * Numéro de scène DÉRIVÉ de la position réelle dans le parcours — fourni par
 * PresentationShell. Remplace les watermarks hardcodés par volet, qui se
 * désynchronisaient à chaque réordonnancement narratif (constat 2026-07-04 :
 * chiffres disait « 16 » en 18ᵉ position). Annexes numérotées « A1 »… « A8 ».
 */

import { createContext, useContext } from "react";

import { VoletWatermark } from "./presentation.styles";

export const SceneNumberContext = createContext<string>("");

/** Filigrane auto-numéroté — à utiliser dans les volets à la place d'un numéro en dur. */
export function AutoWatermark() {
  const num = useContext(SceneNumberContext);
  return <VoletWatermark aria-hidden>{num}</VoletWatermark>;
}
