/**
 * Analytics du moteur de présentation (V6.A — « conversion async traçable »).
 * Colocalisé avec le moteur (le hub `analytics.ts` est déjà énorme — règle 22) ;
 * SOUVERAIN : passe par le singleton `analytics` → Matomo self-hosté EU, jamais
 * d'appel tiers. La catégorie `"presentation"` est déclarée dans l'union du hub.
 *
 * Le `mode` distingue une séance en salle (`live`) d'un deck envoyé en asynchrone
 * (`solo`) : c'est ce qui révèle sur quelle scène un prospect décroche quand on
 * lui envoie la présentation par lien.
 */
import { analytics } from "@/shared/utils/analytics";

/** Mode de lecture d'un deck — dimension analytique clé du chantier A/D. */
export type PresentationPlaybackMode = "live" | "solo" | "kiosk";

/**
 * Signal d'engagement par scène (dwell), consommé par un sink optionnel — le
 * scoring par DESTINATAIRE (#57.2). Matomo agrège tous les modes/decks ; le sink
 * attribue le dwell à un lien nominatif précis (branché par SharedDeckPage sur
 * /deck/:slug). Découplé (le moteur n'importe rien du domaine share-link).
 */
export interface PresentationEngagementSignal {
  sceneId: string;
  sceneIndex: number;
  dwellMs: number;
}

let engagementSink: ((signal: PresentationEngagementSignal) => void) | null =
  null;
let completeSink: (() => void) | null = null;

/**
 * Branche (ou débranche avec `null`) un observateur des dwell de scène. Un seul
 * sink à la fois (une seule présentation solo à l'écran). Best-effort : le sink
 * ne doit jamais throw (il ne casse pas l'analytics Matomo ni la lecture).
 */
export function setPresentationEngagementSink(
  sink: ((signal: PresentationEngagementSignal) => void) | null,
): void {
  engagementSink = sink;
}

/**
 * Branche un observateur de fin de deck (dernière scène atteinte) — déclencheur
 * du CTA de capture lead in-deck (#57.3). Même contrat best-effort que le sink
 * d'engagement.
 */
export function setPresentationCompleteSink(sink: (() => void) | null): void {
  completeSink = sink;
}

export const presentationAnalytics = {
  /** Ouverture d'un deck (1ʳᵉ scène montée). */
  deckStart(
    deckId: string,
    mode: PresentationPlaybackMode,
    sceneCount: number,
  ): void {
    analytics.track({
      category: "presentation",
      action: "deck.start",
      label: deckId,
      value: sceneCount,
      metadata: { deckId, mode, sceneCount },
    });
  },

  /** Entrée sur une scène (funnel de progression). */
  sceneEnter(
    deckId: string,
    mode: PresentationPlaybackMode,
    scene: { id: string; label: string },
    index: number,
  ): void {
    analytics.track({
      category: "presentation",
      action: "scene.enter",
      label: scene.id,
      value: index,
      metadata: {
        deckId,
        mode,
        sceneId: scene.id,
        sceneLabel: scene.label,
        sceneIndex: index,
      },
    });
  },

  /** Sortie d'une scène avec le temps passé (dwell) — cœur de l'analyse de
   *  décrochage : une scène quittée en < 1 s = pas lue, une scène longue =
   *  point d'intérêt. `value` = dwell en ms (moyennes Matomo). */
  sceneLeave(
    deckId: string,
    mode: PresentationPlaybackMode,
    scene: { id: string; label: string },
    index: number,
    dwellMs: number,
  ): void {
    analytics.track({
      category: "presentation",
      action: "scene.leave",
      label: scene.id,
      value: Math.round(dwellMs),
      metadata: {
        deckId,
        mode,
        sceneId: scene.id,
        sceneLabel: scene.label,
        sceneIndex: index,
        dwellMs: Math.round(dwellMs),
      },
    });
    // Attribution par destinataire (#57.2) — best-effort, ne casse pas Matomo.
    if (engagementSink) {
      try {
        engagementSink({
          sceneId: scene.id,
          sceneIndex: index,
          dwellMs: Math.round(dwellMs),
        });
      } catch {
        /* sink défaillant ignoré */
      }
    }
  },

  /** Dernière scène du flux principal atteinte (taux de complétion). */
  deckComplete(
    deckId: string,
    mode: PresentationPlaybackMode,
    sceneCount: number,
  ): void {
    analytics.track({
      category: "presentation",
      action: "deck.complete",
      label: deckId,
      value: sceneCount,
      metadata: { deckId, mode, sceneCount },
    });
    // Déclenche le CTA de capture lead in-deck (#57.3) — best-effort.
    if (completeSink) {
      try {
        completeSink();
      } catch {
        /* sink défaillant ignoré */
      }
    }
  },
};
