import { useCallback, useImperativeHandle, useMemo, useRef, type Ref } from "react";
import { styled } from "styled-components";

import { liensDeLaSphere, pointsDeLaSphere, tourner } from "./geometrie";

/**
 * La sphère de connexions — des points et leurs liens, en volume.
 *
 * Le centre du système du cabinet (héros de la landing avocats). William, le
 * 2026-09-25 : « avec une constellation, un réseau, des connexions autour du
 * terme Juris-Connect ou autour d'une orbe pourquoi pas, mais ne copie pas
 * celle utilisée chez les justiciables ». C'est une orbe faite de connexions :
 * `nombreDePoints` points répartis sans hasard, chacun lié à ses `voisins` plus
 * proches, qui tournent. Rien de commun avec le disque de verre de l'assistant.
 *
 * UNE TOILE (canvas) ET NON DU SVG : 64 points et ~110 liens redessinés à
 * chaque image, c'est 170 nœuds DOM qu'aucun lecteur d'écran n'a à connaître.
 * La toile est décorative ; ce qui la traverse (un nom, un titre) est du texte,
 * posé par la scène par-dessus.
 *
 * Elle ne tourne pas d'elle-même : la scène l'appelle à chaque image
 * (`dessiner`), avec son horloge unique (`horloge.ts`).
 */

export interface PoigneeDeLaSphere {
  /**
   * Redessine la sphère. `lacet` : sa rotation (rad) ; `apparition` ∈ [0, 1] :
   * où en est l'entrée (les points s'allument un à un, les liens suivent) ;
   * `pouls` ∈ [0, 1] : l'éclat d'un battement qui vient d'arriver.
   */
  dessiner: (lacet: number, apparition: number, pouls: number) => void;
}

const Toile = styled.canvas`
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
`;

export function SphereDeConnexions({
  diametre,
  couleur,
  nombreDePoints = 64,
  voisins = 3,
  inclinaison = -0.38,
  densite: agrandissement = 1,
  ref,
}: {
  diametre: number;
  /** L'encre des points et des liens — un jeton de la palette qui l'accueille. */
  couleur: string;
  nombreDePoints?: number;
  voisins?: number;
  /** L'inclinaison fixe de l'axe (rad) : la sphère se montre un peu par-dessus. */
  inclinaison?: number;
  /**
   * L'agrandissement que la scène subit à l'écran (`transform: scale` d'un
   * cadre de planche) : la toile se dessine d'autant plus dense, sans quoi la
   * sphère d'une scène agrandie serait floue. 1 sur la vitrine.
   */
  densite?: number;
  ref?: Ref<PoigneeDeLaSphere>;
}) {
  const toile = useRef<HTMLCanvasElement>(null);
  const points = useMemo(() => pointsDeLaSphere(nombreDePoints), [nombreDePoints]);
  const liens = useMemo(() => liensDeLaSphere(points, voisins), [points, voisins]);

  const dessiner = useCallback(
    (lacet: number, apparition: number, pouls: number) => {
      const c = toile.current;
      const ctx = c?.getContext("2d");
      if (!c || !ctx) return;
      /* La résolution suit l'écran (une toile à 1 px CSS = 1 px serait floue à
         densité 2), et elle se règle ICI plutôt que dans un effet. Au mouvement
         réduit, la scène ne dessine qu'UNE image, depuis un effet de mise en
         page — qui passe avant les effets ordinaires : un effet qui
         redimensionnait la toile ensuite l'effaçait (sphère absente, vue au
         navigateur le 2026-09-25). */
      const densite = Math.min(2, window.devicePixelRatio || 1) * Math.max(1, agrandissement);
      const cote = Math.round(diametre * densite);
      if (c.width !== cote || c.height !== cote) {
        c.width = cote;
        c.height = cote;
      }
      ctx.setTransform(densite, 0, 0, densite, 0, 0);
      const rayon = diametre / 2 - 3;
      const centre = diametre / 2;
      ctx.clearRect(0, 0, diametre, diametre);

      // Le contour : un trait à peine visible, qui donne son volume à la sphère.
      ctx.globalAlpha = 0.16 * apparition;
      ctx.lineWidth = 1;
      ctx.strokeStyle = couleur;
      ctx.beginPath();
      ctx.arc(centre, centre, rayon, 0, Math.PI * 2);
      ctx.stroke();

      const projetes = points.map((p) => {
        const q = tourner(p, lacet, inclinaison);
        return { x: centre + q.x * rayon, y: centre - q.y * rayon, z: q.z };
      });

      // Les liens d'abord, du plus lointain au plus proche.
      ctx.lineWidth = 0.8;
      ctx.strokeStyle = couleur;
      const eclat = 1 + pouls * 0.9;
      for (const [i, j] of liens) {
        const a = projetes[i];
        const b = projetes[j];
        const profondeur = (a.z + b.z) / 2;
        const allume = Math.min(1, Math.max(0, apparition * 1.6 - (i / nombreDePoints) * 0.6));
        ctx.globalAlpha = Math.min(1, (0.08 + 0.34 * ((profondeur + 1) / 2)) * eclat) * allume;
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(b.x, b.y);
        ctx.stroke();
      }

      // Puis les points : plus gros et plus clairs à l'avant, et ceux de
      // l'avant portent un halo — la lumière est de ce côté-ci.
      ctx.fillStyle = couleur;
      projetes.forEach((p, i) => {
        const allume = Math.min(1, Math.max(0, apparition * 1.8 - (i / nombreDePoints) * 0.8));
        if (allume <= 0) return;
        const avant = (p.z + 1) / 2;
        if (avant > 0.72) {
          ctx.globalAlpha = 0.14 * eclat * allume;
          ctx.beginPath();
          ctx.arc(p.x, p.y, 4.5 + 3 * avant, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = Math.min(1, (0.28 + 0.72 * avant) * eclat) * allume;
        ctx.beginPath();
        ctx.arc(p.x, p.y, 0.9 + 1.5 * avant, 0, Math.PI * 2);
        ctx.fill();
      });
      ctx.globalAlpha = 1;
    },
    [diametre, couleur, inclinaison, nombreDePoints, agrandissement, points, liens],
  );

  useImperativeHandle(ref, () => ({ dessiner }), [dessiner]);

  return <Toile ref={toile} aria-hidden="true" />;
}
