/**
 * Le réglage système « réduire les animations », lu À L'APPEL — pour le code
 * impératif qui ne vit pas dans un rendu : un tween GSAP, une horloge de scène.
 *
 * Un composant React lit le réglage par un hook, qui le suit en direct :
 * `useReducedMotion` de framer-motion (ce que font les composants du moteur
 * d'animation) ou `useMotionReduite` (`shared/hooks`). Cette fonction-ci sert
 * là où un hook ne peut pas être appelé.
 *
 * `window.matchMedia` peut manquer (test sans DOM, rendu serveur) : elle rend
 * alors `false` — le comportement animé, celui que les bancs décrivent — plutôt
 * que de lever.
 */
const REQUETE = "(prefers-reduced-motion: reduce)";

export function mouvementReduit(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  try {
    return window.matchMedia(REQUETE).matches;
  } catch {
    return false;
  }
}
