/**
 * Garde plein écran du mode présentation (lot fiabilité jour J, GO user
 * 2026-07-05) : détecte une sortie de plein écran NON demandée (Esc
 * involontaire, alt-tab, dialogue système) et expose un état pour afficher
 * une affordance de ré-entrée pendant ~7 s.
 *
 * `fullscreenchange` est le seul signal fiable (MDN) — la sortie VOLONTAIRE
 * (bouton / touche F) est distinguée via `markVoluntaryExit()`, appelé par le
 * toggle AVANT `exitFullscreen()`.
 */
import { useCallback, useEffect, useRef, useState } from "react";

export function useFullscreenGuard() {
  const [fullscreenLost, setFullscreenLost] = useState(false);
  const wasFullscreenRef = useRef(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    const onFullscreenChange = () => {
      if (document.fullscreenElement) {
        wasFullscreenRef.current = true;
        setFullscreenLost(false);
        return;
      }
      if (wasFullscreenRef.current) {
        wasFullscreenRef.current = false;
        setFullscreenLost(true);
        if (timerRef.current) window.clearTimeout(timerRef.current);
        timerRef.current = window.setTimeout(
          () => setFullscreenLost(false),
          7000,
        );
      }
    };
    document.addEventListener("fullscreenchange", onFullscreenChange);
    return () => {
      document.removeEventListener("fullscreenchange", onFullscreenChange);
      if (timerRef.current) window.clearTimeout(timerRef.current);
    };
  }, []);

  /** À appeler AVANT exitFullscreen() volontaire — pas d'alerte dans ce cas. */
  const markVoluntaryExit = useCallback(() => {
    wasFullscreenRef.current = false;
  }, []);

  const dismissFullscreenLost = useCallback(() => setFullscreenLost(false), []);

  return { fullscreenLost, markVoluntaryExit, dismissFullscreenLost };
}
