/**
 * Wake lock d'écran pour le mode présentation — empêche la mise en veille
 * pendant que le présentateur parle (risque réel jour J : machine inactive
 * au clavier plusieurs minutes par scène).
 *
 * Pattern MDN vérifié (recherche 2026-07-05, Baseline 2025) :
 *  - le lock est AUTOMATIQUEMENT libéré quand le document devient inactif
 *    (onglet caché, fenêtre minimisée) → ré-acquisition sur `visibilitychange` ;
 *  - `navigator.wakeLock.request` peut être REJETÉ (économie d'énergie,
 *    batterie faible, document non visible) → try/catch, jamais bloquant ;
 *  - progressive enhancement : API absente (vieux navigateur de secours) →
 *    no-op silencieux, le deck fonctionne comme avant.
 */
import { useEffect } from "react";

type WakeLockSentinelLike = {
  release: () => Promise<void>;
  released?: boolean;
};

type NavigatorWithWakeLock = Navigator & {
  wakeLock?: { request: (type: "screen") => Promise<WakeLockSentinelLike> };
};

export function useWakeLock(enabled: boolean) {
  useEffect(() => {
    if (!enabled) return;
    const nav = navigator as NavigatorWithWakeLock;
    if (!nav.wakeLock) return; // no-op : navigateur sans l'API

    let sentinel: WakeLockSentinelLike | null = null;
    let disposed = false;

    const acquire = async () => {
      try {
        const acquired = await nav.wakeLock!.request("screen");
        if (disposed) {
          // Unmount pendant l'await (StrictMode double-mount) : release
          // immédiat sinon sentinel zombie jamais libérée (audit 2026-07-05).
          void acquired.release().catch(() => undefined);
          return;
        }
        sentinel = acquired;
      } catch {
        // Rejet système (mode éco, batterie) — non bloquant, on retentera
        // au prochain visibilitychange. Plan B runbook : réglages OS.
        sentinel = null;
      }
    };

    const onVisibilityChange = () => {
      // Le lock a été libéré d'office quand le document est devenu caché →
      // re-demander dès qu'il redevient visible (pattern MDN).
      if (!disposed && document.visibilityState === "visible") {
        void acquire();
      }
    };

    void acquire();
    document.addEventListener("visibilitychange", onVisibilityChange);

    return () => {
      disposed = true;
      document.removeEventListener("visibilitychange", onVisibilityChange);
      void sentinel?.release().catch(() => undefined);
      sentinel = null;
    };
  }, [enabled]);
}
