/* eslint-disable no-console */
/**
 * Logger conditionnel pour Juris-Power
 *
 * En développement : logs complets pour debugging
 * En production : aucun log (sécurité - évite exposition JWT, tokens, données sensibles)
 *
 * Usage:
 *   import { logger } from '@/shared/utils/logger';
 *   logger.log('Message de debug', data);
 *   logger.error('Erreur critique', error);
 *   logger.warn('Attention', warning);
 *   logger.info('Information', info);
 *
 * Pour migrer un console.log existant:
 *   AVANT: console.log('[MeetingContainer] JWT DECODED', decoded);
 *   APRÈS: logger.debug('[MeetingContainer] JWT DECODED', decoded);
 */

import { captureException, isSentryEnabled } from '@/shared/config/sentry.config';
import { Envs } from './env';

type LogLevel = 'debug' | 'info' | 'warn' | 'error';

interface LoggerConfig {
  enabled: boolean;
  minLevel: LogLevel;
}

const LOG_LEVELS: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

const isDevelopment = Envs.ENV === 'development' || Envs.ENV === 'dev';

const config: LoggerConfig = {
  enabled: isDevelopment,
  minLevel: isDevelopment ? 'warn' : 'error', // 'debug' -> 'warn' pour réduire le bruit en console
};

/**
 * Sanitize des données sensibles avant logging (même en dev)
 * Masque les tokens, mots de passe, etc.
 */
function sanitize(data: unknown): unknown {
  if (data === null || data === undefined) return data;

  if (typeof data === 'string') {
    // Masquer les JWT (format: xxx.xxx.xxx)
    if (data.match(/^[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+\.[A-Za-z0-9-_]+$/)) {
      return '[JWT MASKED]';
    }
    // Masquer les UUIDs potentiellement sensibles si très longs
    if (data.length > 100) {
      return data.substring(0, 50) + '...[TRUNCATED]';
    }
    return data;
  }

  if (Array.isArray(data)) {
    return data.map(sanitize);
  }

  if (typeof data === 'object') {
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(data as Record<string, unknown>)) {
      const lowerKey = key.toLowerCase();
      // Masquer les champs sensibles
      if (
        lowerKey.includes('password') ||
        lowerKey.includes('token') ||
        lowerKey.includes('secret') ||
        lowerKey.includes('jwt') ||
        lowerKey.includes('authorization') ||
        lowerKey.includes('apikey') ||
        lowerKey.includes('api_key')
      ) {
        sanitized[key] = '[REDACTED]';
      } else {
        sanitized[key] = sanitize(value);
      }
    }
    return sanitized;
  }

  return data;
}

function shouldLog(level: LogLevel): boolean {
  if (!config.enabled) return false;
  return LOG_LEVELS[level] >= LOG_LEVELS[config.minLevel];
}

/**
 * Override le niveau minimum de logs runtime. Utilise par la page
 * /app/parametres/general (toggle "Mode debug") pour permettre a l'avocat
 * de capturer plus de logs avant de coller au support. Force aussi
 * `enabled=true` quand minLevel='debug' pour que les logs sortent meme
 * en prod.
 */
export function setLogLevel(level: LogLevel): void {
  config.minLevel = level;
  if (level === 'debug') {
    config.enabled = true;
  } else if (!isDevelopment) {
    // En prod, on remet enabled=false sauf si dev (defaut historique).
    config.enabled = false;
  }
}

function formatMessage(level: LogLevel, message: string): string {
  const timestamp = new Date().toISOString().split('T')[1].split('.')[0];
  const prefix = {
    debug: '[DEBUG]',
    info: '[INFO]',
    warn: '[WARN]',
    error: '[ERROR]',
  }[level];
  return `${prefix} [${timestamp}] ${message}`;
}

export const logger = {
  /**
   * Debug - pour le développement uniquement
   * Utiliser pour tracer les flux, données internes
   */
  debug: (message: string, ...args: unknown[]): void => {
    if (shouldLog('debug')) {
      console.log(formatMessage('debug', message), ...args.map(sanitize));
    }
  },

  /**
   * Log - alias de debug pour migration facile depuis console.log
   */
  log: (message: string, ...args: unknown[]): void => {
    if (shouldLog('debug')) {
      console.log(formatMessage('debug', message), ...args.map(sanitize));
    }
  },

  /**
   * Info - informations importantes mais non critiques
   */
  info: (message: string, ...args: unknown[]): void => {
    if (shouldLog('info')) {
      console.info(formatMessage('info', message), ...args.map(sanitize));
    }
  },

  /**
   * Warn - avertissements, comportements inattendus non bloquants
   */
  warn: (message: string, ...args: unknown[]): void => {
    if (shouldLog('warn')) {
      console.warn(formatMessage('warn', message), ...args.map(sanitize));
    }
  },

  /**
   * Error - erreurs critiques
   * Note: En production, considérer l'envoi vers un service de monitoring (Sentry)
   */
  error: (message: string, ...args: unknown[]): void => {
    if (shouldLog('error')) {
      console.error(formatMessage('error', message), ...args.map(sanitize));
    }
    // Send errors to Sentry in non-development environments
    if (!isDevelopment && isSentryEnabled()) {
      const error = args[0] instanceof Error ? args[0] : new Error(message);
      captureException(error, {
        extra: { originalMessage: message, args: args.map(sanitize) },
      });
    }
  },

  /**
   * Group - pour grouper des logs liés
   */
  group: (label: string): void => {
    if (config.enabled) {
      console.group(label);
    }
  },

  groupEnd: (): void => {
    if (config.enabled) {
      console.groupEnd();
    }
  },

  /**
   * Table - pour afficher des données tabulaires
   */
  table: (data: unknown): void => {
    if (shouldLog('debug') && data) {
      console.table(sanitize(data));
    }
  },

  /**
   * Time - pour mesurer les performances
   */
  time: (label: string): void => {
    if (config.enabled) {
      console.time(label);
    }
  },

  timeEnd: (label: string): void => {
    if (config.enabled) {
      console.timeEnd(label);
    }
  },
};

// Export du type pour les modules qui veulent typer le logger
export type Logger = typeof logger;
