/**
 * Design System - Motion Tokens
 *
 * Systeme complet de timing, easing, springs et staggers.
 * Source de verite pour TOUTES les animations du projet.
 * Plus AUCUN magic number dans les composants.
 *
 * Usage :
 *   import { motion as m } from '@/shared/design-tokens/motion';
 *   transition={{ ...m.spring.snappy }}
 *   transition={{ duration: m.duration.normal, ease: m.ease.out }}
 */

// ============================================
// DURATIONS (en secondes, pour Framer Motion / GSAP)
// ============================================
export const duration = {
  /** 0.1s — Toggle, checkbox, tooltip appear */
  instant: 0.1,
  /** 0.15s — Button feedback, micro-interactions */
  fast: 0.15,
  /** 0.25s — Standard UI transitions */
  normal: 0.25,
  /** 0.35s — Modal, panel, card entrance */
  medium: 0.35,
  /** 0.5s — Page transition, hero entrance */
  slow: 0.5,
  /** 0.8s — Cinematic reveal, text split */
  cinematic: 0.8,
  /** 1.2s — Dramatic entrance, first-view hero */
  dramatic: 1.2,
} as const;

// ============================================
// SPRINGS (Framer Motion / GSAP spring configs)
// ============================================
export const spring = {
  /** Doux — modals, overlays, panneaux (mouvement naturel, pas de rebond) */
  gentle: { type: 'spring' as const, stiffness: 120, damping: 20, mass: 1 },
  /** Reactif — boutons, feedbacks, toggles (rapide, precis) */
  snappy: { type: 'spring' as const, stiffness: 400, damping: 28, mass: 0.8 },
  /** Rebondissant — success, celebrations, pop-in (overshoot visible) */
  bouncy: { type: 'spring' as const, stiffness: 300, damping: 12, mass: 1 },
  /** Fluide — slides, drag, layout (mouvement continu, zero rebond) */
  smooth: { type: 'spring' as const, stiffness: 200, damping: 30, mass: 1 },
  /** Lourd — elements importants, transitions majeures (gravitas) */
  heavy: { type: 'spring' as const, stiffness: 150, damping: 25, mass: 1.5 },
  /** Press — feedback bouton (enfoncement rapide, retour bounce) */
  press: { type: 'spring' as const, stiffness: 500, damping: 15, mass: 0.5 },
} as const;

// ============================================
// EASING CURVES (CSS cubic-bezier + Framer Motion arrays)
// ============================================
export const ease = {
  /** Entree douce — elements qui arrivent (deceleration) */
  out: [0.16, 1, 0.3, 1] as [number, number, number, number],
  /** Sortie — elements qui partent (acceleration) */
  in: [0.4, 0, 1, 1] as [number, number, number, number],
  /** Standard — mouvement neutre */
  inOut: [0.65, 0, 0.35, 1] as [number, number, number, number],
  /** Overshoot — pop-in avec depassement */
  outBack: [0.34, 1.56, 0.64, 1] as [number, number, number, number],
  /** Emphatic — entree dramatique */
  emphatic: [0.22, 1, 0.36, 1] as [number, number, number, number],
  /**
   * Keynote — la courbe des planches : douce mais decidee. Nee dans le deck du
   * barreau de Saint-Malo (2026-07), recopiee en dur dans 23 fichiers avant
   * d'etre un jeton (2026-10-14). GSAP la porte sous le nom `keynote`
   * (`shared/animations/gsap.ts`).
   */
  keynote: [0.22, 0.61, 0.36, 1] as [number, number, number, number],
} as const;

/** CSS cubic-bezier strings (pour styled-components / CSS transitions) */
export const easeCss = {
  out: 'cubic-bezier(0.16, 1, 0.3, 1)',
  in: 'cubic-bezier(0.4, 0, 1, 1)',
  inOut: 'cubic-bezier(0.65, 0, 0.35, 1)',
  outBack: 'cubic-bezier(0.34, 1.56, 0.64, 1)',
  emphatic: 'cubic-bezier(0.22, 1, 0.36, 1)',
  keynote: 'cubic-bezier(0.22, 0.61, 0.36, 1)',
} as const;

// ============================================
// STAGGER DELAYS (en secondes)
// ============================================
export const stagger = {
  /** 0.03s — Listes rapides (notifications, menu items) */
  fast: 0.03,
  /** 0.06s — Cartes, grilles */
  normal: 0.06,
  /** 0.1s — Elements importants, sections */
  slow: 0.1,
  /** 0.15s — Hero elements, first-view reveals */
  dramatic: 0.15,
} as const;

// ============================================
// PRESETS FRAMER MOTION (prets a spreader)
// ============================================
export const presets = {
  /** Apparition standard avec montee */
  fadeUp: {
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    exit: { opacity: 0, y: -10 },
    transition: { duration: duration.medium, ease: ease.out },
  },
  /** Apparition avec scale depuis le centre */
  scaleIn: {
    initial: { opacity: 0, scale: 0.92 },
    animate: { opacity: 1, scale: 1 },
    exit: { opacity: 0, scale: 0.95 },
    transition: spring.gentle,
  },
  /** Slide depuis la droite (overlay, drawer) */
  slideRight: {
    initial: { opacity: 0, x: 80 },
    animate: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: 40 },
    transition: spring.smooth,
  },
  /** Pop avec rebond (badge, notification, success) */
  popBounce: {
    initial: { opacity: 0, scale: 0.5 },
    animate: { opacity: 1, scale: 1 },
    exit: { opacity: 0, scale: 0.8 },
    transition: spring.bouncy,
  },
  /** Pression bouton (whileTap + whileHover) */
  buttonPress: {
    whileHover: { scale: 1.03, y: -1, transition: { duration: duration.fast } },
    whileTap: { scale: 0.97, y: 1, transition: spring.press },
  },
  /** Hover carte premium (lift + shadow expand) */
  cardHover: {
    whileHover: {
      y: -6,
      transition: { duration: duration.normal, ease: ease.out },
    },
  },
  /** Hero entrance — spectacular first-view reveal (scale + fade + blur) */
  heroEntrance: {
    initial: { opacity: 0, y: 40, scale: 0.96, filter: 'blur(8px)' },
    animate: { opacity: 1, y: 0, scale: 1, filter: 'blur(0px)' },
    exit: { opacity: 0, y: -20, scale: 0.98 },
    transition: { duration: duration.cinematic, ease: ease.emphatic },
  },
  /** Button pulse — subtle CTA attention grab (use with animate) */
  buttonPulse: {
    animate: {
      boxShadow: [
        '0 0 0 0 rgba(0, 119, 204, 0.3)',
        '0 0 0 8px rgba(0, 119, 204, 0)',
        '0 0 0 0 rgba(0, 119, 204, 0)',
      ],
      transition: { duration: 2, repeat: Infinity, ease: 'easeInOut' },
    },
  },
  /** Card reveal — staggered card entrance for grids */
  cardReveal: {
    initial: { opacity: 0, y: 24, scale: 0.97 },
    animate: { opacity: 1, y: 0, scale: 1 },
    exit: { opacity: 0, scale: 0.98 },
    transition: { duration: duration.medium, ease: ease.out },
  },
} as const;

// ============================================
// CSS TRANSITION STRINGS (pour styled-components)
// ============================================
export const cssTransition = {
  fast: `${duration.fast}s ${easeCss.out}`,
  normal: `${duration.normal}s ${easeCss.out}`,
  medium: `${duration.medium}s ${easeCss.out}`,
  slow: `${duration.slow}s ${easeCss.out}`,
  /** Proprietes GPU-only (transform + opacity) — jamais de layout thrash */
  gpuTransform: `transform ${duration.normal}s ${easeCss.out}, opacity ${duration.normal}s ${easeCss.out}`,
  gpuAll: `transform ${duration.normal}s ${easeCss.out}, opacity ${duration.normal}s ${easeCss.out}, box-shadow ${duration.normal}s ${easeCss.out}, filter ${duration.normal}s ${easeCss.out}`,
} as const;

// Re-export tout sous un namespace unique
export const motionTokens = {
  duration,
  spring,
  ease,
  easeCss,
  stagger,
  presets,
  cssTransition,
} as const;
