/**
 * Le réseau du cabinet, en données : les nœuds (les services et leur place de
 * départ), les liens, les mesures de la scène selon sa largeur, et la
 * composition de départ qui montre le plus de libellés.
 *
 * Pur : la scène le lit, le banc le joue.
 */
import {
  SERVICES_DE_LA_MARQUE,
  type IdServiceDeLaMarque,
  type OrbiteDuService,
} from "@/shared/config/services-de-la-marque";

import type { TaillesLues } from "./reseau.types";
import { LIENS_DU_RESEAU } from "./systeme.flux";
import {
  anglesDeLOrbite,
  libellesMasques,
  projeterSurOrbite,
  type Boite,
  type Disque,
  type ObjetALEcran,
  type Point2,
  type Projection,
} from "@/shared/animations/scene/geometrie";

export interface NoeudDuReseau {
  readonly id: IdServiceDeLaMarque;
  readonly libelle: string;
  readonly glyphe: string;
  readonly orbite: OrbiteDuService;
  readonly tiroir: boolean;
  /** L'angle au repos, avant toute rotation (rad). */
  readonly angle: number;
}

/**
 * Les nœuds dans l'ordre de TABULATION : la consultation d'abord, le cabinet
 * ensuite, chacun dans l'ordre de la couverture LinkedIn.
 *
 * Les angles de départ évitent l'axe du fond (−π/2) : un service posé juste
 * derrière la sphère y serait caché, et c'est là que la composition fixe du
 * mouvement réduit le laisserait pour toujours.
 */
export const NOEUDS_DU_RESEAU: readonly NoeudDuReseau[] = (() => {
  const parOrbite = (orbite: OrbiteDuService) =>
    SERVICES_DE_LA_MARQUE.filter((s) => s.orbite === orbite);
  const consultation = parOrbite("consultation");
  const cabinet = parOrbite("cabinet");
  const anglesConsultation = anglesDeLOrbite(consultation.length, -Math.PI / 2 + Math.PI / 5);
  const anglesCabinet = anglesDeLOrbite(cabinet.length, -Math.PI / 2 + Math.PI / cabinet.length / 2);
  const noeud = (s: (typeof SERVICES_DE_LA_MARQUE)[number], angle: number): NoeudDuReseau => ({
    id: s.id,
    libelle: s.libelle,
    glyphe: s.glyphe,
    orbite: s.orbite,
    tiroir: "tiroir" in s && s.tiroir === true,
    angle,
  });
  return [
    ...consultation.map((s, i) => noeud(s, anglesConsultation[i])),
    ...cabinet.map((s, i) => noeud(s, anglesCabinet[i])),
  ];
})();

/** L'index d'un nœud par son identifiant. */
export const INDEX_DU_NOEUD: ReadonlyMap<IdServiceDeLaMarque, number> = new Map(
  NOEUDS_DU_RESEAU.map((n, i) => [n.id, i]),
);

/** Les liens, en index de nœuds. */
export const LIENS_EN_INDEX: ReadonlyArray<readonly [number, number]> = LIENS_DU_RESEAU.map(
  ([a, b]) => [INDEX_DU_NOEUD.get(a) ?? 0, INDEX_DU_NOEUD.get(b) ?? 0] as const,
);

/**
 * En dessous, le système passe à la frise.
 *
 * 640 ET NON 750. Les 750 px venaient du croquis V6 (2026-09-23), mesurés sur
 * la CONSTELLATION, dont les libellés se touchaient en dessous. Repris tels
 * quels, ils ont fait basculer en frise le héros d'un écran de 1 280 px (scène
 * de 701 px, 2026-09-25) : réseau sans libellé, douze lignes de frise dans la
 * colonne de droite, et le titre repoussé sous la ligne de flottaison. Le
 * système tient ses libellés dès 640 px — l'occlusion fait taire ceux que
 * recouvre un objet plus proche, et le banc vérifie que ceux de côté restent
 * dans le cadre à cette largeur.
 */
export const LARGEUR_MIN_SYSTEME = 640;

/** Les mesures d'une scène de `largeur` × `hauteur` pixels. */
export interface MesuresDeLaScene {
  readonly largeur: number;
  readonly hauteur: number;
  readonly cx: number;
  readonly cy: number;
  readonly rayonConsultation: number;
  readonly rayonCabinet: number;
  readonly aplatissement: number;
  readonly focale: number;
  readonly diametreSphere: number;
  /** Rayon RENDU du disque d'un service à l'échelle 1 — px(62) ou px(40) × 0,8 :
   *  il ancre le service sur son disque, et arrête les filaments à son bord. */
  readonly rayonDisque: number;
  readonly compacte: boolean;
}

/**
 * LE SYSTÈME COMPLET, à partir de `LARGEUR_MIN_SYSTEME` px de scène ; en
 * dessous, la vue de face, compacte et sans libellé.
 *
 * Les proportions sont MESURÉES au navigateur sur la scène de 1 440 px
 * (795 × 673, 2026-09-25) :
 *   · un premier jet à plat (aplatissement 0,42) ramassait tout le réseau sur
 *     un tiers de la hauteur, et les deux orbites s'y chevauchaient — il passe
 *     à 0,6, vu davantage par-dessus ;
 *   · la consultation serre la sphère (20 % de la largeur), le cabinet s'en
 *     écarte (37 %) : les libellés de côté restent dans le cadre (180 px) ;
 *   · le centre est à 43 % de la hauteur : le fond de l'orbite monte moins que
 *     l'avant ne descend, libellés compris.
 */
export function mesurerLaScene(largeur: number, hauteur: number): MesuresDeLaScene {
  const compacte = largeur < LARGEUR_MIN_SYSTEME;
  if (compacte) {
    return {
      largeur,
      hauteur,
      cx: largeur / 2,
      cy: hauteur / 2,
      rayonConsultation: largeur * 0.25,
      rayonCabinet: largeur * 0.41,
      aplatissement: 0.72,
      focale: 1e6,
      diametreSphere: Math.max(96, largeur * 0.3),
      rayonDisque: 16,
      compacte,
    };
  }
  return {
    largeur,
    hauteur,
    cx: largeur / 2,
    cy: hauteur * 0.43,
    rayonConsultation: largeur * 0.2,
    rayonCabinet: largeur * 0.37,
    aplatissement: 0.6,
    focale: 1600,
    diametreSphere: Math.min(210, Math.max(150, largeur * 0.24)),
    rayonDisque: 24.8,
    compacte,
  };
}

/* ───────────────────────── La scène à l'écran, pour l'occlusion ───────────────────────── */

/** Le centre tel que l'occlusion le voit : la sphère, et le TEXTE du terme (sans son voile). */
export function centreALEcran(me: MesuresDeLaScene, tailles: TaillesLues): { sphere: Disque; terme: Boite } {
  return {
    sphere: { x: me.cx, y: me.cy, r: (me.diametreSphere / 2) * 0.96 },
    terme: {
      x: me.cx - tailles.terme.l / 2,
      y: me.cy - tailles.terme.h / 2,
      l: tailles.terme.l,
      h: tailles.terme.h,
    },
  };
}

/**
 * Les services tels que l'occlusion les voit à une image : le disque rendu, la
 * profondeur RÉELLE (en pixels — deux orbites se comparent ainsi) et la boîte
 * du libellé, mesurée une fois par changement de taille.
 */
export function servicesALEcran(
  projections: readonly Projection[],
  rayons: readonly number[],
  tailles: TaillesLues,
  me: MesuresDeLaScene,
): ObjetALEcran[] {
  return projections.map((p, i) => {
    const t = tailles.libelles[i];
    return {
      disque: { x: p.x, y: p.y, r: me.rayonDisque * p.echelle },
      z: p.profondeur * rayons[i],
      libelle: t ? { x: p.x + t.dx, y: p.y + t.dy, l: t.l, h: t.h } : null,
    };
  });
}

/**
 * LA COMPOSITION DE DÉPART — de combien tourner chaque orbite avant le premier
 * geste pour que le moins de libellés possible se taisent.
 *
 * Au mouvement réduit, rien ne tourne : cette composition est la SEULE que le
 * visiteur verra. Vu au navigateur le 2026-09-25 : posés à leurs angles de
 * départ, six libellés sur douze se taisaient à 1 200 px, recouverts par un
 * voisin plus proche. Ailleurs, c'est la première impression.
 *
 * Une grille de `pas` × `pas` phases, évaluée une fois par changement de taille
 * (quelques millisecondes : 576 compositions de douze services). À égalité avec
 * les angles de la source, la source l'emporte ; sinon, la première trouvée.
 */
export function compositionDeDepart(
  me: MesuresDeLaScene,
  tailles: TaillesLues,
  pas = 24,
): { consultation: number; cabinet: number } {
  const scene = { cx: me.cx, cy: me.cy, aplatissement: me.aplatissement, focale: me.focale };
  const rayons = NOEUDS_DU_RESEAU.map((n) => (n.orbite === "consultation" ? me.rayonConsultation : me.rayonCabinet));
  const centre = centreALEcran(me, tailles);
  const tus = (consultation: number, cabinet: number) => {
    const projections = NOEUDS_DU_RESEAU.map((n, i) =>
      projeterSurOrbite(n.angle + (n.orbite === "consultation" ? consultation : cabinet), rayons[i], scene),
    );
    return libellesMasques(servicesALEcran(projections, rayons, tailles, me), centre, null).filter(Boolean).length;
  };
  let meilleure = { consultation: 0, cabinet: 0 };
  let moins = tus(0, 0);
  for (let i = 0; i < pas && moins > 0; i++) {
    for (let j = 0; j < pas && moins > 0; j++) {
      const consultation = (i / pas) * 2 * Math.PI;
      const cabinet = (j / pas) * 2 * Math.PI;
      const n = tus(consultation, cabinet);
      if (n < moins) {
        moins = n;
        meilleure = { consultation, cabinet };
      }
    }
  }
  return meilleure;
}

/**
 * L'ENTRÉE DISPERSÉE d'une planche (pitch du 2026-10-15) : avant d'être reliés,
 * les services flottent épars, chacun à sa place, loin du centre — « une
 * dizaine d'outils qui ne se parlent pas ». Places déterministes (angle d'or,
 * deux couronnes), dans le cadre de la scène, jamais sur le terme central.
 */
export function placesDeLaDispersion(me: MesuresDeLaScene): Point2[] {
  const n = NOEUDS_DU_RESEAU.length;
  const angleDOr = Math.PI * (3 - Math.sqrt(5));
  return NOEUDS_DU_RESEAU.map((_, i) => {
    const couronne = i % 2 === 0 ? 0.88 : 0.62;
    const a = i * angleDOr + 0.4;
    return {
      x: me.cx + Math.cos(a) * (me.largeur / 2) * couronne * (0.92 + 0.08 * ((i * 7) % n) / n),
      y: me.cy + Math.sin(a) * (me.hauteur / 2) * couronne * 0.86,
    };
  });
}

/**
 * Un service entre la dispersion et son orbite : `k` va de 0 (épars, à la
 * dérive) à 1 (sur l'orbite) — au-delà de 1 pendant le ressort, d'où le
 * dépassement. La dérive s'éteint à mesure qu'il s'accroche.
 */
export function placeEntreDispersionEtOrbite(
  depart: Point2,
  orbite: Projection,
  k: number,
  derive: number,
  i: number,
): Projection {
  const libre = Math.max(0, 1 - k);
  const x0 = depart.x + Math.sin(derive / 1700 + i * 1.3) * 7 * libre;
  const y0 = depart.y + Math.cos(derive / 2100 + i * 0.9) * 5 * libre;
  return {
    ...orbite,
    x: x0 + (orbite.x - x0) * k,
    y: y0 + (orbite.y - y0) * k,
    echelle: 0.85 + (orbite.echelle - 0.85) * Math.min(1, Math.max(0, k)),
  };
}
