/**
 * Le rythme d'un battement, en millisecondes à la cadence 1 : toutes les 3,8 s,
 * le trait voyage 1,3 s, puis la carte vit 2,5 s. Exporté pour qu'une planche
 * qui pilote les battements cale ses propres gestes sur l'arrivée du trait (la
 * Pitch Night pose un tampon sur le dossier à chaque arrivée) au lieu d'en
 * recopier les valeurs.
 */
export const RYTHME_DU_FLUX = { periodeMs: 3_800, traitMs: 1_300, carteMs: 2_500 } as const;

/** Les liens que le réseau dessine : un par paire de services qui se parlent. */
export const LIENS_DU_RESEAU: ReadonlyArray<readonly [IdServiceDeLaMarque, IdServiceDeLaMarque]> =
  (() => {
    const vus = new Set<string>();
    const liens: Array<readonly [IdServiceDeLaMarque, IdServiceDeLaMarque]> = [];
    for (const { de, vers } of BATTEMENTS) {
      const cle = [de, vers].sort().join("|");
      if (vus.has(cle)) continue;
      vus.add(cle);
      liens.push([de, vers]);
    }
    return liens;
  })();
