import { useEffect, useRef, type RefObject } from "react";

/**
 * L'horloge d'une scène — UN seul `requestAnimationFrame` pour toute la scène,
 * et il sait s'arrêter. Née pour le système du cabinet (héros de la landing
 * avocats), remontée dans le moteur d'animation le 2026-10-14 : une planche de
 * présentation la partage.
 *
 * Il ne tourne que si trois conditions tiennent ensemble :
 *   · l'appelant le veut (`actif`) — faux en mouvement réduit ;
 *   · la scène est à l'écran — une scène qu'on a fait défiler hors de vue
 *     n'a pas à dessiner soixante images par seconde ;
 *   · l'onglet est visible.
 *
 * Il ne passe PAS par l'état React : à chaque image, `aChaqueImage` reçoit le
 * temps écoulé et écrit lui-même dans le DOM (`poser`). Un rendu React par
 * image rejouerait tout l'arbre de la scène.
 *
 * `dt` est borné à 64 ms : au retour d'un onglet caché, la scène reprend là
 * où elle s'était arrêtée au lieu de sauter d'un tour.
 */
export function useHorlogeDeScene(
  aChaqueImage: (dtMs: number, maintenant: number) => void,
  { actif, cible }: { actif: boolean; cible: RefObject<Element | null> },
): void {
  const rappel = useRef(aChaqueImage);
  rappel.current = aChaqueImage;

  useEffect(() => {
    if (!actif) return;
    const element = cible.current;
    let aLEcran = true;
    let visible = typeof document === "undefined" || document.visibilityState !== "hidden";
    let image = 0;
    let precedent = 0;

    const boucle = (maintenant: number) => {
      const dt = precedent ? Math.min(64, maintenant - precedent) : 16;
      precedent = maintenant;
      rappel.current(dt, maintenant);
      image = requestAnimationFrame(boucle);
    };
    const demarrer = () => {
      if (image || !aLEcran || !visible) return;
      precedent = 0;
      image = requestAnimationFrame(boucle);
    };
    const arreter = () => {
      if (image) cancelAnimationFrame(image);
      image = 0;
    };

    const observateur =
      element && typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver((entrees) => {
            aLEcran = entrees.some((e) => e.isIntersecting);
            if (aLEcran) demarrer();
            else arreter();
          })
        : null;
    if (observateur && element) observateur.observe(element);

    const auChangementDOnglet = () => {
      visible = document.visibilityState !== "hidden";
      if (visible) demarrer();
      else arreter();
    };
    document.addEventListener("visibilitychange", auChangementDOnglet);

    demarrer();
    return () => {
      arreter();
      observateur?.disconnect();
      document.removeEventListener("visibilitychange", auChangementDOnglet);
    };
  }, [actif, cible]);
}

/**
 * N'écrit un attribut que s'il change : écrire à chaque image, même la même
 * valeur, réveille le calcul du style. La discipline de l'horloge : on écrit
 * ce qui bouge, rien d'autre.
 */
export function poser(el: Element, nom: string, valeur: string): void {
  if (el.getAttribute(nom) !== valeur) el.setAttribute(nom, valeur);
}
