/**
 * SoloOverlay — surcouche visuelle des modes AUTO-GUIDÉS (V6.A solo + V6.D
 * kiosk). Extrait du shell (règle 22/23) : badge « lecture auto »/« boucle » +
 * barre de dwell en lecture, pastille « reprendre » quand le spectateur a repris
 * la main. Rien hors mode auto-guidé ; en solo, rien à la dernière scène (plus
 * rien à avancer). En kiosk, la barre tourne en continu (pas de fin).
 */
import type { CSSProperties } from "react";

import type { PresentationPlaybackMode } from "./presentation-analytics";
import {
  SoloBadge,
  SoloProgressFill,
  SoloProgressTrack,
  SoloResumePill,
} from "./presentation-solo.styles";

interface SoloOverlayProps {
  /** Un mode auto-guidé (solo ou kiosk) est actif. */
  active: boolean;
  mode: PresentationPlaybackMode;
  atMainEnd: boolean;
  autoPaused: boolean;
  dark?: boolean;
  dwellMs: number;
  /** `index-step` — redémarre la barre de dwell à chaque pas. */
  stepKey: string;
  onResume: () => void;
}

export function SoloOverlay({
  active,
  mode,
  atMainEnd,
  autoPaused,
  dark,
  dwellMs,
  stepKey,
  onResume,
}: SoloOverlayProps) {
  const isKiosk = mode === "kiosk";
  // Solo : plus rien à montrer à la fin. Kiosk : la boucle continue → on garde
  // l'overlay même « au bout » (l'instant avant le rebouclage).
  if (!active || (atMainEnd && !isKiosk)) return null;

  if (autoPaused) {
    return (
      <SoloResumePill
        type="button"
        onClick={onResume}
        aria-label="Reprendre la lecture automatique du diaporama"
      >
        ▶ Reprendre la lecture auto
      </SoloResumePill>
    );
  }

  const fillStyle: CSSProperties = {
    animationDuration: `${Math.max(1200, dwellMs)}ms`,
  };
  return (
    <>
      <SoloProgressTrack aria-hidden>
        <SoloProgressFill key={stepKey} style={fillStyle} />
      </SoloProgressTrack>
      <SoloBadge $dark={dark}>
        {isKiosk
          ? "🔁 Boucle continue"
          : "▶ Lecture auto · flèches pour piloter"}
      </SoloBadge>
    </>
  );
}
